char HW[102][102];

void DFS(int Y,int X,char c)
{
	char check=c;
	if(HW[Y][X]=='0'||HW[Y][X]!=check)
		return;

	HW[Y][X]='0';

	DFS(Y-1,X,c);
	DFS(Y,X+1,c);
	DFS(Y+1,X,c);
	DFS(Y,X-1,c);
}	

