{	
	int i,nx,ny;
	if(arr[x][y]==obj)
	{
		vis[x][y]=1;
		for(i=0;i<4;i++)
		{
			nx=x+dx[i];
			ny=y+dy[i];
			if(!vis[nx][ny]&&(nx>=0&&nx<h)&&(ny>=0&&ny<w))
				dfs(obj,nx,ny);		
		}
	}
	else
		return;
}
int main() 
{
	while(scanf("%d%d",&h,&w),h||w)
	{
		int i,j,num=0;
