char farm[101][101];

void dfs(int x, int y, char s){
	farm[x][y]='^';

	for(int i=0;i<4;i++){
		for(int j=0;j<4;j++){
			int nx=x+dx[i],ny=y+dy[i];
			if(nx<0 || W<=nx) continue;
			if(ny<0 || H<=ny) continue;
			if(farm[nx][ny] != s) continue;
			else dfs(nx, ny, s);
		}
	}
	return;
}

