			col[a - 1][b] = cnt;
			Q.push((a - 1) * 10000 + b);
		}
		if (x[a][b] == x[a + 1][b] && col[a + 1][b] == 0) {
			col[a + 1][b] = cnt;
			Q.push((a + 1) * 10000 + b);
		}
		if (x[a][b] == x[a][b - 1] && col[a][b - 1] == 0) {
			col[a][b - 1] = cnt;
			Q.push(a * 10000 + (b - 1));
		}
		if (x[a][b] == x[a][b + 1] && col[a][b + 1] == 0) {
			col[a][b + 1] = cnt;
			Q.push(a * 10000 + (b + 1));
		}
	}
}

