    for (int nx = x - 1; nx <= x + 1; nx += 2) {
        if (0 <= nx && nx < w && field[y][nx] == ch) {
            searchCompartment(nx, y, h, w, field);
        }
    }
    for (int ny = y - 1; ny <= y + 1; ny += 2) {
        if (0 <= ny && ny < h && field[ny][x] == ch) {
            searchCompartment(x, ny, h, w, field);
        }
    }
}

