int solve(int h, int w, vector<string> &v){
    int count = 0;
    REP(y,h){
        REP(x,w){
            deque<pair<int,int> > q;
            q.pb(mp(x,y));
            if(v[y][x] == '.') continue;
            char tp = v[y][x];
            count++;
            v[y][x] = '.';
            while(!q.empty()){
                int x0 = q.front().first;
                int y0 = q.front().second;
                REP(i,4){
                    int mx = x0 + dir[i][0];
                    int my = y0 + dir[i][1];
                    if(mx < 0 || mx >= w || my < 0 || my >= h) continue;
                    if(v[my][mx] == tp){
                        q.pb(mp(mx,my));
                        v[my][mx] = '.';
                    }
                }
                q.pop_front();
            }
            REP(y,h) pr(v[y]);
        }
    }
    return count;
}

