void move(string area[], int i, int j, char ch, int h, int w){
	area[i][j] = '.';
	if(i - 1 >= 0 && area[i-1][j] == ch) move(area, i - 1, j, ch, h, w);
	if(i + 1 < h && area[i+1][j] == ch) move(area, i + 1, j, ch, h, w);
	if(j - 1 >= 0 && area[i][j-1] == ch) move(area, i, j - 1, ch, h, w);
	if(j + 1 < w && area[i][j+1] == ch) move(area, i, j + 1, ch, h, w);
}

