void dfs(char c, int x, int y)
{
	data[x][y] = '0';

	if (data[x + 1][y] == c){
		dfs(data[x + 1][y], x + 1, y);
	}
	if (data[x - 1][y] == c && 0 <= (x - 1)){
		dfs(data[x - 1][y], x - 1, y);
	}
	if (data[x][y + 1] == c){
		dfs(data[x][y + 1], x, y + 1);
	}
	if (data[x][y - 1] == c && 0 <= (y - 1)){
		dfs(data[x][y - 1], x, y - 1);
	}

	return;
}

