#include <vector>

template<typename Weight>
class Edge {
public:
	using weight_t = Weight;

	int src, dst;
	weight_t weight;

	Edge(){}
	Edge(int dst): src(-1), dst(dst), weight(1){}
	Edge(int dst, weight_t weight): dst(dst), weight(weight){}
	Edge(int src, int dst, weight_t weight): src(src), dst(dst), weight(weight){}
};

template<typename Weight, bool Undirected = false>
class Graph {
public:
	using weight_t = Weight;
	using edge_t = Edge<Weight>;
	static const bool undirected = Undirected;

	Graph(): n(0){}
	Graph(int n): n(n), es(n){}

	int size() const {
		return n;
	}

	void addEdge(int src, int dst, weight_t weight = 1){
		es[src].emplace_back(src, dst, weight);
		if (undirected){
			es[dst].emplace_back(dst, src, weight);
		}
	}

	const std::vector<edge_t>& operator[](int v) const {
		return es[v];
	}

	typename std::vector<std::vector<edge_t>>::const_iterator begin() const {
		return std::begin(es);
	}

	typename std::vector<std::vector<edge_t>>::const_iterator end() const {
		return std::end(es);
	}

private:
	int n;
	std::vector<std::vector<edge_t>> es;
};
