#include <vector>
#include <string>
#include <tuple>
#include <algorithm>
#include <cstring>
#include <utility>

template<typename Strings, typename Weight>
Graph<Weight, false> buildGridGraph(const Strings &s, const std::vector<std::tuple<char, char, Weight>> &es, int height, int width)
{
	Graph<Weight, false> g(height * width);
	auto to1d = [&](int i, int j){ return i * width + j; };

	static Weight w[256][256];
	bool f[256][256] = {};

	for (const auto &e : es){
		w[std::get<0>(e)][std::get<1>(e)] = std::get<2>(e);
		f[std::get<0>(e)][std::get<1>(e)] = true;
	}

	for (int i = 0; i < height; i++){
		for (int j = 0; j < width; j++){
			if (i + 1 < height){
				if (f[s[i][j]][s[i + 1][j]]){
					g.addEdge(to1d(i, j), to1d(i + 1, j), w[s[i][j]][s[i + 1][j]]);
				}
				if (f[s[i + 1][j]][s[i][j]]){
					g.addEdge(to1d(i + 1, j), to1d(i, j), w[s[i + 1][j]][s[i][j]]);
				}
			}
			if (j + 1 < width){
				if (f[s[i][j]][s[i][j + 1]]){
					g.addEdge(to1d(i, j), to1d(i, j + 1), w[s[i][j]][s[i][j + 1]]);
				}
				if (f[s[i][j + 1]][s[i][j]]){
					g.addEdge(to1d(i, j + 1), to1d(i, j), w[s[i][j + 1]][s[i][j]]);
				}
			}
		}
	}

	return std::move(g);
}

template<typename Weight>
Graph<Weight, false> buildGridGraph(const std::vector<std::string> &s, const std::vector<std::tuple<char, char, Weight>> &es)
{
	return buildGridGraph(s, es, s.size(), s[0].size());
}
