int main()
{
	const vector<tuple<char, char, int>> T = {
		mt('#', '#', 1),
		mt('*', '*', 1),
		mt('@', '@', 1)
	};

	int h, w;
	while (cin >> h >> w, h){
		vector<string> s(h);
		for (auto &r : s) cin >> r;
		auto g = buildGridGraph(s, T);
		UnionFind uf(g.size());
		for (auto &&es : g) for (auto &&e : es){
			uf.unite(e.src, e.dst);
		}
		cout << uf.count() << endl;
	}
}

