#include <iostream>
using namespace std;

void rec( char c, char* map, int x, int y, int w, int h )
{
	static int diff[][ 2 ] = { { 0, -1 }, { 1, 0 }, { 0, 1 }, { -1, 0 } };

	if( map[ y * w + x ] != c ){
		return;
	}

	map[ y * w + x ] = 0;

	for( int i = 0; i < 4; ++i ){
		rec( c, map, x + diff[ i ][ 0 ], y + diff[ i ][ 1 ], w, h );
	}

	return;
}

int main()
{
	int h, w;

	while( cin >> h >> w && !( h == 0 && w == 0 ) ){
		if( h == 0 || w == 0 ){
			cout << 0 << endl;
			continue;
		}

		int hh = h + 2;
		int ww = w + 2;
		char* map = new char[ ww * hh ]();

		for( int i = 0; i < h; ++i ){
			cin >> &map[ ( i + 1 ) * ww + 1 ];
		}

		int areaCount = 0;
		for( int i = 1; i < hh; ++i ){
			for( int j = 1; j < ww; ++j ){
				char c =  map[ i * ww + j ];
				if( c == 0 ){
					continue;
				}
				rec( c, map, j, i, ww, hh );
				++areaCount;
			}
		}

		cout << areaCount << endl;

		delete[] map;
	}

	return 0;
}

#include <iostream>
using namespace std;

char mas[100][101];
int w,h;
int grx[4]={0,1,0,-1},gry[4]={1,0,-1,0};

void sha(int,int);
void as(int,int);
void at(int,int);

int main(){
  int cnt;
  while(1){
    cin >> w >> h;
    cnt = 0;
    if(w == 0 && h == 0) break;
    for(int i=0;i<h;i++){
      for(int j=0;j<w;j++){
	cin >> mas[i][j];
      }
    }
    for(int i=0;i<w;i++){
      for(int j=0;j<h;j++){
	if(mas[i][j] == '#'){
	  sha(j,i);
	  cnt++;
	}
	else if(mas[i][j] == '*'){
	  as(j,i);
	  cnt++;
	}
	else if(mas[i][j] == '@'){
	  at(j,i);
	  cnt++;
	}
      }
    }
    cout << cnt << endl;
  }
}

void sha(int x,int y){
  mas[y][x] = '0';
  for(int i=0;i<4;i++){
    int nx = x + grx[i];
    int ny = y + gry[i];
    if(nx >= 0 && nx < w && ny >= 0 && ny < h && mas[ny][nx] == '#'){
      sha(nx,ny);
    }
  }
}

void as(int x,int y){
  mas[y][x] = '0';
  for(int i=0;i<4;i++){
    int nx = x + grx[i];
    int ny = y + gry[i];
    if(nx >= 0 && nx < w && ny >= 0 && ny < h && mas[ny][nx] == '*'){
      as(nx,ny);
    }
  }
}

void at(int x,int y){
  mas[y][x] = '0';
  for(int i=0;i<4;i++){
    int nx = x + grx[i];
    int ny = y + gry[i];
    if(nx >= 0 && nx < w && ny >= 0 && ny < h && mas[ny][nx] == '@'){
      at(nx,ny);
    }
  }
}

#include <stdio.h>
#include <queue>
using namespace std;


int main()
{
	int map[102][102];		//数値変換した果樹園のマップ
	char in[101];			//入力文字列
	int y,x;				//果樹園の大きさh,w
	int i,j,r;				//ループ用変数
	int ty[4] = {1,-1,0,0},tx[4] = {0,0,1,-1};	//四方向の移動量
	int temp;				//作業用
	queue< pair<int,int> > que;	//幅優先探索用のキュー
	pair<int,int> P,NP;		//pair型:任意の型２つをまとめて扱うことのできる型

	scanf("%d%d",&y,&x);

	while(y != 0 && x != 0){
		//初期化
		for(i = 0; i <= y+1; i++){
			map[0][i] = 0;
			map[x+1][i] = 0;
		}
		for(i = 0; i <= x+1; i++){
			map[i][0] = 0;
			map[i][y+1] = 0;
		}

		//入力
		for(j = 1; j <= y; j++){
			scanf("%s",in);
			//マップの数値化
			//しなくてもいいけど私はこうした方が分かり易いのでやる
			for(i = 1; i <= x; i++){
				if(in[i-1] == '#'){
					map[i][j] = -1;
				}
				else if(in[i-1] == '*'){
					map[i][j] = -2;
				}
				else if(in[i-1] == '@'){
					map[i][j] = -3;
				}
			}
		}

		//連続した部分の探索
		int c = 0;	//c:連続した区間の数
		for(j = 1; j <= y; j++){
			for(i = 1; i <= x; i++){
				if(map[i][j] < 0){
					//printf("現在地:%d,%d\n",i,j);
					c++;
					//幅優先開始
					//P:現在地 NP:移動後の地点
					//temp:スタート地のマップの種類
					P.first = i;
					P.second = j;
					temp = map[P.first][P.second];
					map[P.first][P.second] = c;
					que.push(P);
					while(!que.empty()){
						P = que.front();
						//4方向を見る
						for(r = 0; r < 4; r++){
							//もし現在地の果物の種類が移動後の位置の果物の種類と同じなら
							if(temp == map[P.first + tx[r]][P.second + ty[r]]){
								NP.first = P.first + tx[r];
								NP.second = P.second + ty[r];
								map[NP.first][NP.second] = c;
								que.push(NP);
							}
						}
						que.pop();
					}
				}
			}
		}

		/*デバッグ用出力:mapの出力
		for(i = 0; i <= y+1; i++){
			for(j = 0; j <= x+1; j++){
				printf("%2d",map[j][i]);
			}
			printf("\n");
		}*/

		printf("%d\n",c);


		scanf("%d%d",&y,&x);
	}

	return 0;
}

