vector<vector<char> > hata;

void dfs(int x, int y, char c) {
  hata[y][x] = 0;

  for(int k = -1; k <= 1; k++ ) {
    int nx = x+k;
    int ny = y+k;

    if(nx >= 0 && nx < m && hata[y][nx] == c) dfs(nx, y, c);
    if(ny >= 0 && ny < n && hata[ny][x] == c) dfs(x, ny, c);
  }
  return;
}

