    for(int i = 0; i < n; i++ ) {
      for(int j = 0; j < m; j++ ) {
        if(hata[i][j] != 0) {
          dfs(j, i, hata[i][j]);
          cnt++;
        }
      }
    }
    cout << cnt << endl;
    cin >> m >> n;
  }
  return 0;
}

