typedef	pair<int,int>	pii;

pii forest[100][100];

pii UF_root(pii p){return forest[p.y][p.x].x==-1?p:forest[p.y][p.x]=UF_root(forest[p.y][p.x]);}
void UF_union(pii p,pii q){p=UF_root(p);q=UF_root(q);forest[q.y][q.x]=p;}
bool UF_find(pii p,pii q){return UF_root(p)==UF_root(q);}

int main()
{
	int dx[]={-1,0},dy[]={0,-1};

	char garden[100][101];
	for(int h,w;cin>>h>>w,h;){
