		for(int i=0;i<h;i++)for(int j=0;j<w;j++){
			for(int k=0;k<2;k++){
				int xx=j+dx[k],yy=i+dy[k];
				if(0<=xx && xx<w && 0<=yy && yy<h){
					if(garden[i][j]==garden[yy][xx] && !UF_find(mp(j,i),mp(xx,yy)))
						UF_union(mp(j,i),mp(xx,yy));
