		}

		memset(flag, 0, sizeof(flag));
		memset(vis, 0, sizeof(vis));


		posn node;

		for(int i = 0; i < x; ++ i)
		{
			for(int j = 0; j < y; ++ j)
			{
				if(!flag[i][j])
				{
					node.x = i;
					node.y = j;
					flag[i][j] = s;
					que.push(node);
					bfs();
					s ++;
				}
			}
		}

		printf("%d\n", traverse());
	}	

	return 0;
}

