int vy[4] = {0,0,1,-1};

void back(char c, int i, int j){
	check[i][j] = true;
	for(int k=0;k<4;k++){
		int pi,pj;
		pi = i + vx[k];
		pj = j + vy[k];
		if(-1<pi && pi<h && -1<pj && pj<w){
			if(board[pi][pj] == c && !check[pi][pj]){
				back(c,pi,pj);
			}
		}
	}
}

int solve(){
	int sum=0;
	for(int i=0;i<h;i++){
		for(int j=0;j<w;j++){
