bool dfs (int row, int col, char p, vector <string> d, vector <vector <bool> >& used )
{
	// order up right down left
	const int dir[][2] = { { -1, 0 }, { 0, 1 }, { 1, 0 }, { 0, -1 } };
	int size = d.size();
	int len  = d[0].size();
	int k;

	if (used[row][col] ){
		return false;
	} // end if

	used[row][col] = true;

	for (k = 0; k < 4; ++k){
		int nrow = row + dir[k][0];
		int ncol = col + dir[k][1];
		if (nrow < 0 || nrow >= size || ncol < 0 || ncol >= len ){
			continue;
		} // end if
		if (!used[nrow][ncol] && d[nrow][ncol] == p ){
			if (dfs (nrow, ncol, p, d, used )){
				return true;
			} // end if
		} // end if
	} // end for

	return false;
}


