#include <iostream>

int m, n, res;
char mat[102][102];

void dfs(char p, int x, int y) {
    if (x < 0 || x >= m || y < 0 || y >= n || mat[x][y] != p) {
        return;
    }
    mat[x][y] = '.';
    dfs(p, x-1, y);
    dfs(p, x+1, y);
    dfs(p, x, y-1);
    dfs(p, x, y+1);
}

void solve() {
    res = 0;
    for (int i = 0; i < m; i++) {
        std::cin >> mat[i];
    }
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == '.') {
                continue;
            }
            dfs(mat[i][j], i, j);
            res++;
        }
    }
}

int main() {
    while (std::cin >> m >> n && m > 0 && n > 0) {
        solve();
        std::cout << res << std::endl;
    }
    return 0;
}

#include<iostream>
using namespace std;

int farm[101][101];

void kubun(int k,int a,int b){
	farm[a][b]=0;
	if(k==farm[a-1][b])kubun(farm[a-1][b],a-1,b);
	if(k==farm[a+1][b])kubun(farm[a+1][b],a+1,b);
	if(k==farm[a][b-1])kubun(farm[a][b-1],a,b-1);
	if(k==farm[a][b+1])kubun(farm[a][b+1],a,b+1);

}
int main(){
	char c[101][101];
	int a,b;
	int h,w;
	int ans=0;
	while(1){
		ans=0;
		for(b=0;b<101;b++){
			for(a=0;a<101;a++){
				farm[a][b]=0;
			}
		}
		scanf("%d %d",&h,&w);
		if(h==0 && w==0)break;
		for(b=0;b<w;b++){
			cin >> c[b];
			for(a=0;a<h;a++){
				if(c[b][a]=='@')farm[a][b]=1;
				if(c[b][a]=='#')farm[a][b]=2;
				if(c[b][a]=='*')farm[a][b]=3;

			}
		}
		for(b=0;b<w;b++){
			for(a=0;a<h;a++){
				if(farm[a][b]==0);
				else{
					ans++;
					kubun(farm[a][b],a,b); 
				}
			}
		}
		printf("%d\n",ans);
	}
	return 0;
}

