void Dfs(int x, int y) {
  checked[x][y] = true;

  int dx[4] = {1, 0, -1, 0};
  int dy[4] = {0, 1, 0, -1};
  REP(i, 4) {
    int nx = x+dx[i];
    int ny = y+dy[i];
    if (0 <= nx && nx < H && 0 <= ny && ny < W) {
      if (!checked[nx][ny] && field[nx][ny] == field[x][y]) { Dfs(nx, ny); }
    }
  }

  return;
}

