  ans = 0;
  fill(checked[0], checked[kMaxH-1]+1, false);

  REP(i, H) {
    REP(j, W) {
      if (!checked[i][j]) {
        Dfs(i, j);
        ++ans;
      }
    }
  }

  cout << ans << endl;
  return true;
}

