#include <iostream>
using namespace std;

bool ion[100][100];
char room[100][100];
int w, h;

void infection(int nowi,int nowj,bool ion[100][100],int w,int h) {
	ion[nowi][nowj] = 1;
	if (nowi-1>=0)
	{
		if (room[nowi][nowj]==room[nowi-1][nowj]&&ion[nowi-1][nowj]==0)
		{
			infection(nowi-1,nowj,ion,w,h);
		}
	}
	if (nowi+1<h)
	{
		if (room[nowi][nowj] == room[nowi + 1][nowj]&&ion[nowi+1][nowj]==0)
		{
			infection(nowi + 1, nowj, ion, w, h);
		}
	}
	if (nowj-1>=0)
	{
		if (room[nowi][nowj] == room[nowi][nowj-1]&&ion[nowi][nowj-1]==0)
		{
			infection(nowi, nowj-1, ion, w, h);
		}
	}
	if (nowj+1<w)
	{
		if (room[nowi][nowj] == room[nowi][nowj+1]&&ion[nowi][nowj+1]==0)
		{
			infection(nowi, nowj+1, ion, w, h);
		}
	}
}


int main() {
	while (cin >> w >> h) {
		if (w*h == 0)
		{
			return 0;
		}
		for (int i = 0; i < h; i++)
		{
			for (int j = 0; j < w; j++)
			{
				cin >> room[i][j];
				ion[i][j] = 0;
			}

		}
		int num = 0;
		for (int i = 0; i < h; i++)
		{
			for (int j = 0; j < w; j++)
			{
				if (ion[i][j] == 0)
				{
					infection(i, j, ion, w, h);
					num++;
				}

			}

		}
		cout << num << endl;
	}


}

#include <iostream>
#include <stack>
#include <utility>

using namespace std;
typedef pair<int,int> pii;

#define foreach(i, n) for (typeof(n) i = 0; i < (n); ++i)

inline bool between(int lower, int upper, int x) { return lower <= x && x < upper; }
inline bool between(pii lower, pii upper, pii x) {
    return between(lower.first, upper.first, x.first)
        && between(lower.second, upper.second, x.second);
}
pii dirctions[4] = { pii(0,-1), pii(0,1), pii(-1,0), pii(1,0) };
template <typename S, typename T> inline
pair<S,T> operator+(const pair<S,T> & p, const pair<S,T> & q) {
    return pair<S,T>(p.first + q.first, p.second + q.second);
}

#define MAX_H 100
#define MAX_W 100

int H, W;
char data[MAX_H][MAX_W];
stack<pii> stk;

int main() {
    while (true) {
        cin >> H >> W;
        if (H == 0 && W == 0) break;
        foreach (i, H) foreach (j, W) cin >> data[i][j];

        int cnt = 0;
        foreach (i, H) {
            foreach (j, W) {
                char self = data[i][j];
                if (not self) continue;
                ++ cnt;
                stk.push(pii(i,j));
                while (not stk.empty()) {
                    pii pos = stk.top();
                    stk.pop();
                    foreach (d, 4) {
                        pii nxt = pos + dirctions[d];
                        if (not between(pii(0,0), pii(H,W), nxt)) continue;
                        if (data[nxt.first][nxt.second] != self) continue;
                        data[nxt.first][nxt.second] = 0;
                        stk.push(nxt);
                    }
                }
