typedef long long int lint;

void paint(int H, int W, int** map, int x, int y, int kind)
{
	if (x < 0 || x >= W) return;
	if (y < 0 || y >= H) return;
	if (map[y][x] != kind) return;
	map[y][x] = -1;
	paint(H, W, map, x - 1, y, kind);
	paint(H, W, map, x + 1, y, kind);
	paint(H, W, map, x, y - 1, kind);
	paint(H, W, map, x, y + 1, kind);
}

int solve(int H, int W, int** map)
{
	int count = 0;
	for (int y = 0; y < H; y++){
		for (int x = 0; x < W; x++){
			if (map[y][x] == -1) continue;
			paint(H, W, map, x, y, map[y][x]);
			count++;
		}
	}
	return count;
}

