char d[100][100];
int H, W;
int ans[20];
char tmp;
int i = 0;
int solve(int a, int b) {
	tmp = d[a][b];
	d[a][b] = 'a';
	if (b + 1 < W && d[a][b + 1] == tmp) {
		d[a][b + 1] = 'a';
		solve(a, b + 1);
	}
	if (a + 1 < H && d[a + 1][b] == tmp) {
		d[a + 1][b] = 'a';
		solve(a+1,b);
	}
	if (a - 1 >= 0 && d[a - 1][b] == tmp) {
		d[a - 1][b] = 'a';
		solve(a-1,b);
	}
	if (b - 1 >= 0 && d[a][b - 1] == tmp) {
		d[a][b - 1] = 'a';
		solve(a,b-1);
	}
	return 0;
}
