		for (int i = 0; i < H; i++) {
			for (int j = 0; j < W; j++) {
				if (d[i][j] != 'a') {
					ans[i]++;
					tmp = d[i][j];
					solve(i, j);
				}
			}
		}
		std::cout << ans[i] << "\n";
		i++;
	}
	return 0;
}

