using namespace std;

void destroy ( vector<string>& field, int i, int j, int symbol ) {
  if( field[ i ][ j ] == symbol ) {
    int symbol = field[ i ][ j ];
    field[ i ][ j ] = '-';
    destroy( field, i - 1, j,     symbol );
    destroy( field, i + 1, j,     symbol );
    destroy( field, i    , j - 1, symbol );
    destroy( field, i    , j + 1, symbol );
  }
}

int search ( vector<string>& field, int i, int j ) {
  static int counter = 0;
  if( i == 1 && j == 1 ) { counter = 0; }
  if( field[ i ][ j ] == '-' ) { return counter; }
  counter++;
  int symbol = field[ i ][ j ];
  field[ i ][ j ] = '-';
  destroy( field, i - 1, j,     symbol );
  destroy( field, i + 1, j,     symbol );
  destroy( field, i    , j - 1, symbol );
  destroy( field, i    , j + 1, symbol );
  return counter;
}


int main() {
  while( 1 ) {
    int h, w;
    cin >> h >> w;
    if( !( h | w ) ) { return EXIT_SUCCESS; }

    vector<string> field;
    field.reserve( h + 2 );

    field[ 0 ] = "";
    field[ h + 1 ] = "";
    for( int j = 0; j <= h + 1; j++ ) {
      field[ 0 ] += "-";
      field[ h + 1 ] += "-";
    }

    for( int i = 1; i <= h ; i++ ) {
      cin >> field[ i ];
      field[ i ] = "-" + field[ i ] + "-";
    }

    int n;
    for( int i = 1; i <= h; i++ ) {
      for( int j = 1; j <= w; j++ ) {
        n = search( field, i, j );
      }
    }
    cout << n << endl;
  }
}

#include <stdio.h>
#include <queue>
using namespace std;


int main()
{
	int map[101][101];		//数値変換した果樹園のマップ
	char in[101];			//入力文字列
	int y,x;				//果樹園の大きさh,w
	int i,j,r;				//ループ用変数
	int ty[4] = {1,-1,0,0},tx[4] = {0,0,1,-1};	//四方向の移動量
	int temp;				//作業用
	queue<pair<int,int>> que;	//幅優先探索用のキュー
	pair<int,int> P,NP;		//pair型:任意の型２つをまとめて扱うことのできる型

	scanf("%d%d",&y,&x);

	while(y != 0 && x != 0){
		//初期化
		for(i = 0; i <= y+1; i++){
			map[0][i] = 0;
			map[x+1][i] = 0;
		}
		for(i = 0; i <= x+1; i++){
			map[i][0] = 0;
			map[i][y+1] = 0;
		}

		//入力
		for(j = 1; j <= y; j++){
			scanf("%s",in);
			//マップの数値化
			//しなくてもいいけど私はこうした方が分かり易いのでやる
			for(i = 1; i <= x; i++){
				if(in[i-1] == '#'){
					map[i][j] = -1;
				}
				else if(in[i-1] == '*'){
					map[i][j] = -2;
				}
				else if(in[i-1] == '@'){
					map[i][j] = -3;
				}
			}
		}

		//連続した部分の探索
		int c = 0;	//c:連続した区間の数
		for(j = 1; j <= y; j++){
			for(i = 1; i <= x; i++){
				if(map[i][j] < 0){
					printf("現在地:%d,%d\n",i,j);
					c++;
					//幅優先開始
					//P:現在地 NP:移動後の地点
					//temp:スタート地のマップの種類
					P.first = i;
					P.second = j;
					temp = map[P.first][P.second];
					map[P.first][P.second] = c;
					que.push(P);
					while(!que.empty()){
						P = que.front();
						//4方向を見る
						for(r = 0; r < 4; r++){
							//もし現在地の果物の種類が移動後の位置の果物の種類と同じなら
							if(temp == map[P.first + tx[r]][P.second + ty[r]]){
								NP.first = P.first + tx[r];
								NP.second = P.second + ty[r];
								map[NP.first][NP.second] = c;
								que.push(NP);
							}
						}
						que.pop();
					}
				}
			}
		}

		/*デバッグ用出力:mapの出力
		for(i = 0; i <= y+1; i++){
			for(j = 0; j <= x+1; j++){
				printf("%2d",map[j][i]);
			}
			printf("\n");
		}*/

		printf("%d\n",c);


		scanf("%d%d",&y,&x);
	}

	return 0;
}

