        if(h == 0 and w == 0){
            return 0;
        }

        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                seen[i][j] = false;
            }
        }

        UnionFind uf(h * w);

        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                cin >> C[i][j];
            }
        }

        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                dfs(i, j, C[i][j], uf);
            }
        }

        set<int> st;
        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                st.insert(uf.root(i * w + j));
            }
        }

        cout << st.size() << endl;
    }

    return 0;
}

