#define H_size 100
#define W_size 100

using namespace std;

size_t num = 0;
char list[H_size][W_size];

void getNum(char(*a)[W_size], char c, size_t i, size_t j, size_t &W, size_t &H) {
	if (i < 0 || j < 0 || i >= H || j >= W || a[i][j] !=c) {
		return;
	}
	if (a[i][j] == c)
	{

		a[i][j] = '.';
		getNum(a, c, i - 1, j, W, H);
		getNum(a, c, i, j + 1, W, H);
		getNum(a, c, i + 1, j, W, H);
		getNum(a, c, i, j - 1, W, H);
		return;
	}
}

int main() {

	vector<int> result;
	size_t W, H;


	while (true) {
		num = 0;
		cin >> W >> H;
		getchar();
		if (W == 0 && H == 0) {
			break;
		}
		else {
			for (size_t i = 0; i < H; ++i)
			{
				cin.getline(list[i], W + 1);
			}
		}
		for (size_t i = 0; i < H; ++i) {
			for (size_t j = 0; j < W; ++j)
			{
				if (list[i][j] != '.') {
					getNum(list, list[i][j], i, j, W, H);
					num++;
				}
			}
		}
		result.push_back(num);

	}

	for (vector<int>::iterator it = result.begin(); it != result.end(); ++it) {
		cout << *it << endl;
	}
	return 0;
}

