const int MAX_H = 100;
const int MAX_W = 100;

int dp[ MAX_H + 1][ MAX_W + 1] = {};

int dy[4] = {1,0,-1,0};
int dx[4] = {0,1,0,-1};

int h, w;

void dfs(int y, int x, int item) {
  dp[y][x] = 0;
  REP(i,4) {
    int nx = x + dx[i];
    int ny = y + dy[i];
    if(nx >= 0 && nx < w && ny >= 0 && ny < h && dp[ny][nx] != 0 && dp[ny][nx] == item ) dfs(ny, nx, item);
  }
  return;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int zero;
  char c;
  int count = 0;

  cin >> h >> w;

  REP(i, h) {
    REP(j, w) {
      cin >> c;
      switch(c) {
        case '@':
          dp[i][j] = 1;
          break;
        case '#':
          dp[i][j] = 2;
          break;
        case '*':
          dp[i][j] = 3;
          break;
        default:
          break;
      }
    }
  }

  cin >> zero >> zero;

  REP(i, h) {
    REP(j, w) {
      if(dp[i][j] != 0) {
        dfs(i, j, dp[i][j]);
        count++;
      }
    }
  }

  cout << count << endl;

  return 0;
}

