char F[102][102];
void DFS(int x,int y,char z){
    if(F[x][y]!=z)
        return;

    F[x][y]='.';

    DFS(x-1,y,z);
    DFS(x,y+1,z);
    DFS(x+1,y,z);
    DFS(x,y-1,z);
}

int main(){
