        for(int x=1;x<=H;x++){
          for(int y=1;y<=W;y++){
             if(F[x][y]=='#'){
                    cnt++;
                    DFS(x,y,'#');
             }
                if(F[x][y]=='@'){
                    cnt++;
                    DFS(x,y,'@');
                }
                if(F[x][y]=='*'){
                    cnt++;
                    DFS(x,y,'*');
                }
            }
        }
        cout<<cnt<<endl;
    }
    return 0;
}

