struct union_find
{
	vector<int> par;
	union_find(int n) :par(n, -1) {}
	int find(int x) { return par[x] < 0 ? x : par[x] = find(par[x]); }
	void unite(int x, int y)
	{
		x = find(x); y = find(y);
		if (x == y) return;
		if (par[y] < par[x]) swap(x, y);
		if (par[x] == par[y]) par[x]--;
		par[y] = x;
		if (find(x) != find(y)) par[find(y)] = x;
	}
	bool same(int x, int y) { return find(x) == find(y); };
	int count()
	{
		int cnt = 0;
		REP(i, par.size()) if (par[i] < 0) cnt++;
		return cnt;
	}
};

int main()
{
	int h, w;
	while (cin >> h >> w, h)
	{
		union_find uft(h*w);
		vs fld(h);
		REP(i, h) cin >> fld[i];
		REP(i, h)REP(j, w)
		{
			REP(k, 4)
			{
				int nx = i + dx[k];
				int ny = j + dy[k];
				if (valid(nx, ny, h, w) && fld[i][j] == fld[nx][ny])
				{
					uft.unite(i*w + j, nx*w + ny);
				}
			}
		}
		cout << uft.count() << endl;
	}
	return 0;
}

