		if(H==W && W==0) break;
		for(int i=0;i<H;i++){
			getline(cin,str);
			for(int j=0;j<W;j++){
				stage[i][j] = str[j];
			}
		}

		cout << bfs(stage,W,H) << endl;

	}
}

