void grouping(int h,int w,char f){
  map[h][w] = '.';
  if(h-1>=0&&map[h-1][w]==f){
    grouping(h-1,w,f);
  }
  if(h+1<H&&map[h+1][w]==f){
    grouping(h+1,w,f);
  }
  if(w-1>=0&&map[h][w-1]==f){
    grouping(h,w-1,f);
  }
  if(w+1<W&&map[h][w+1]==f){
    grouping(h,w+1,f);
  }
}

