    int res = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (Garden[i][j] != 'S') {
                dfs(i, j);
                res++;
            }
        }
    }

    printf("%d\n", res);
}

