void dfs(int i, int j, char tree) {
  // cout << "depth i=" << i << " j=" << j << endl;
  // 今いるところが果樹園の外か、treeでないならreturn
  if (i < 0 || i >= h || j < 0 || j >= w || counted[i][j] || tree != orchard[i][j])
    return;
  // 今いる場所のcountedをtrueにする
  counted[i][j] = true;

  // 4方向に進む
  for (int k = 0; k < 4; k++) {
    dfs(i + dy[k], j + dx[k], tree);
  }
}

