        counted[i][j] = false;
      }
    }
    // 計算
    int res = 0;
    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        if (!counted[i][j]) {
          char tree = orchard[i][j];
          dfs(i, j, tree);
          res++;
        }
      }
    }

    // 出力
    cout << res << endl;
  }
}

