    Orchard orc(height, width);

    int count;
    for (int i=0; i<height; i++)    //メイン処理
    {
      for (int j=0; j<width; j++)
      {
        char fruit = orc.CheckFruit(i, j);
        if ( fruit == 'x' ) continue;
        count++;
        orc.rmFruit( fruit, i, j);
      }
    }
    cout << count << endl;

  }
}

