void dfs(int x, int y){
    for (int i = 0; i < 4; ++i) {
        int nextx = x + dx[i];
        int nexty = y + dy[i];

        if (nextx >=0 && nextx < H && nexty < W && nexty >= 0){
            if (!visited[nextx][nexty]){
                if ( A[x][y] == A[nextx][nexty]){
                    visited[nextx][nexty] = true;
