#include <iostream>

using namespace std;

#define MAX 100
#define FOR(index,max) for(int index=0;index<max;index++)

void visit(int shurui,int i,int j,int *state,int H,int W){
    if(i<0||i>H-1||j<0||j>W-1) return ;
    if(state[i*W+j]!=shurui) return ;
    state[i*W+j]=0;
    visit(shurui,i+1,j,state,H,W);
    visit(shurui,i-1,j,state,H,W);
    visit(shurui,i,j+1,state,H,W);
    visit(shurui,i,j-1,state,H,W);
    return ;
}

int main(){
    int state[MAX*MAX];
    int H,W;
    char in;
    int ans=0;
    while(1){
        cin>>H>>W;
        if(H==0&&W==0) break;
        FOR(i,H){
            FOR(j,W){
                cin>>in;
                if(in=='@') state[i*W+j]=1;
                if(in=='#') state[i*W+j]=2;
                if(in=='*') state[i*W+j]=3;
            }
        }

        FOR(i,H){
            FOR(j,W){
                if(state[i*W+j]!=0){
                    visit(state[i*W+j],i,j,state,H,W);
                    ans++;
                }
            }
        }

        cout<<ans<<endl;
    }

    return 0;
}

#include<iostream>
using namespace std;
const int MAXN = 200;
char B[MAXN][MAXN];
int W,H,cnt;

int dx[5] = {1,0,-1,0};
int dy[5] = {0,1,0,-1};

void isStar(int y, int x)
{
	for(int i =0 ; i<5;i++)
		if(B[y+dy[i]][x+dx[i]]=='*')
			{B[y+dy[i]][x+dx[i]]='0';isStar(y+dy[i],x+dx[i]);}
}

void isSharp(int y, int x)
{
	for(int i =0 ; i<5;i++)
		if(B[y+dy[i]][x+dx[i]]=='#')
			{B[y+dy[i]][x+dx[i]]='0';isSharp(y+dy[i],x+dx[i]);}
}

void isAt(int y, int x)
{
	for(int i =0 ; i<5;i++)
		if(B[y+dy[i]][x+dx[i]]=='@')
			{B[y+dy[i]][x+dx[i]]='0';isAt(y+dy[i],x+dx[i]);}
}



void solve()
{

	for(int i = 1; i<=H;i++)
		for(int j = 1; j<=W;j++)
		{
			if(B[i][j] == '*')
			{
				B[i][j] = '0';
				cnt++;
				isStar(i,j);
			}
			else if(B[i][j] == '#')
			{
				B[i][j] = '0';
				cnt++;
				isSharp(i,j);
			}
			else if(B[i][j] == '@')
			{
				B[i][j] = '0';
				cnt++;
				isAt(i,j);
			}
		}

	cout << cnt<<endl;
}

int main()
{



	while(cin >>H>> W && W||H)
	{
		memset(B,'0',sizeof(B));

		for(int i = 1; i<= H; i++)
		{
			for(int j = 1; j<= W; j++)
				cin >> B[i][j];
		getchar();
		}
		cnt = 0;
		solve();
	}
}

