int main()
{
	int a, b;
	while (cin >> a >> b, a)
	{
		vector<vector<int>>data;
		data.resize(a + 2);
		for (size_t i = 0; i < a + 2; i++)
		{
			data[i].resize(b + 2);
		}
		for (size_t i = 1; i <= a; i++)
		{
			for (size_t j = 1; j <= b; j++)
			{
				char c;
				cin >> c;
				switch (c)
				{
					case '#':
						data[i][j] = 1;
						break;
					case '*':
						data[i][j] = 2;
						break;
					case '@':
						data[i][j] = 3;
						break;
					default:
						break;
				}
			}
		}
		int ans = 0;
		queue<pair<int, int>>d;
		for (size_t i = 1; i <= a; i++)
		{
			for (size_t j = 1; j <= b; j++)
			{
				if (data[i][j])
				{
					ans++;
					int memo = data[i][j];
					data[i][j] = 0;
					d.push(pair<int, int>(i, j));
					while (!d.empty())
					{
						pair<int, int>p = d.front();
						d.pop();
						for (size_t k = 0; k < 4; k++)
						{
							if (data[p.first + dx[k]][p.second + dy[k]] == memo)
							{
								data[p.first + dx[k]][p.second + dy[k]] = 0;
								d.push(pair<int, int>(p.first + dx[k], p.second + dy[k]));
							}
						}
					}
				}
			}
		}
		cout << ans << endl;
	}
}

