void DFS(int y,int x,char f){

	if(T[y][x]!=f)
		return;

	T[y][x]='?';

	DFS(y-1,x  ,f);
	DFS(y-1,x+1,f);
	DFS(y  ,x+1,f);
	DFS(y+1,x+1,f);
	DFS(y+1,x  ,f);
	DFS(y+1,x-1,f);
	DFS(y  ,x-1,f);
	DFS(y-1,x-1,f);
}

