	for(int i=1;i<=h;i++){
		for(int j=1;j<=w;j++){
			if(T[i][j]=='@'){
				count++;
				DFS(i,j,@);
			}
		}

	}

	for(int i=1;i<=h;i++){
		for(int j=1;j<=w;j++){
			if(T[i][j]=='#'){
				count++;
				DFS(i,j,#);
			}
		}

	}

	for(int i=1;i<=h;i++){
		for(int j=1;j<=w;j++){
			if(T[i][j]=='*'){
				count++;
				DFS(i,j,*);
			}
		}

	}

	cout<<count<<endl;

	return 0;
}

