    if (j + 1 < W) {
        if (tmp == m[i][j+1]) dfs(i, j+1, m);
    }
    if (i + 1 < H) {
        if (tmp == m[i+1][j]) dfs(i+1, j, m);
    }
    if (j - 1 >= 0) {
        if (tmp == m[i][j-1]) dfs(i, j-1, m);
