  if (table[r][c] != ch) return;
  table[r][c] = '.';
  dfs(r + 1, c, R, C, ch);
  dfs(r - 1, c, R, C, ch);
  dfs(r, c + 1, R, C, ch);
  dfs(r, c - 1, R, C, ch);
}

