			map[i][y+1] = 0;
		}

		//入力
		for(j = 1; j <= y; j++){
			scanf("%s",in);
			//マップの数値化
			//しなくてもいいけど私はこうした方が分かり易いのでやる
			for(i = 1; i <= x; i++){
				if(in[i-1] == '#'){
					map[i][j] = -1;
				}
				else if(in[i-1] == '*'){
					map[i][j] = -2;
				}
				else if(in[i-1] == '@'){
					map[i][j] = -3;
				}
			}
		}

		//連続した部分の探索
		int c = 0;	//c:連続した区間の数
		for(j = 1; j <= y; j++){
			for(i = 1; i <= x; i++){
				if(map[i][j] < 0){
					printf("現在地:%d,%d\n",i,j);
					c++;
					//幅優先開始
					//P:現在地 NP:移動後の地点
					//temp:スタート地のマップの種類
					P.first = i;
					P.second = j;
					temp = map[P.first][P.second];
					map[P.first][P.second] = c;
					que.push(P);
					while(!que.empty()){
						P = que.front();
						//4方向を見る
						for(r = 0; r < 4; r++){
							//もし現在地の果物の種類が移動後の位置の果物の種類と同じなら
							if(temp == map[P.first + tx[r]][P.second + ty[r]]){
								NP.first = P.first + tx[r];
								NP.second = P.second + ty[r];
								map[NP.first][NP.second] = c;
								que.push(NP);
							}
						}
						que.pop();
					}
				}
			}
		}

		/*デバッグ用出力:mapの出力
		for(i = 0; i <= y+1; i++){
			for(j = 0; j <= x+1; j++){
				printf("%2d",map[j][i]);
			}
			printf("\n");
		}*/

		printf("%d\n",c);


		scanf("%d%d",&y,&x);
	}

	return 0;
}

