				if (c == '#') { x[i][j] = 2; }
				if (c == '*') { x[i][j] = 3; }
			}
		}
		for (int i = 1; i <= h; i++) {
			for (int j = 1; j <= w; j++) {
				if (col[i][j] == 0) {
					Q.push(i*MAX_N + j);
					cnt++;
					col[i][j] = cnt;
					bfs(x[i][j]);
				}
			}
		}
		cout << cnt << endl;
	}
}

