  if (y + 1 < H && c == map[y + 1][x]){
    orchard(y + 1, x, map[y + 1][x]);
  }
  if (y - 1 >= 0 && c == map[y - 1][x]){
    orchard(y - 1, x, map[y - 1][x]);
  }
}

