bool inside( vector<string> &field, int i, int j )
{
	return 0 <= i && i < field.size() && 0 <= j && j < field[i].length();
}

int bfs( vector<string> &field, int i, int j, char c )
{
	if ( field[i][j] != c )
	{
		return 0;
	}

	field[i][j] = ' ';

	const int direction[][2] = {
		0, 1,
		1, 0,
		0, -1,
		-1, 0
	};

	REP( d, 0, 4 )
	{
		int ti = i + direction[d][0];
		int tj = j + direction[d][1];

		if ( inside( field, ti, tj ) )
		{
			bfs( field, ti, tj, c );
		}
	}

	return 1;
}

