void dfs(vector<string>& matrix, int n, int m, int x, int y, const char t) {
    if(x < 0 || x >= n || y < 0 || y >= m || matrix[x][y] != t) return;
    matrix[x][y] = 'x';
    dfs(matrix, n, m, x-1, y, t);
    dfs(matrix, n, m, x+1, y, t);
    dfs(matrix, n, m, x, y-1, t);
    dfs(matrix, n, m, x, y+1, t);
}

void solve(vector<string>& matrix, int n, int m) {
    int count = 0;
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < m; j++) {
            if(matrix[i][j] != 'x') {
                dfs(matrix, n, m, i, j, matrix[i][j]);
                count++;
            }
        }
    }

    cout << count << "\n";
}

