int ans = 0;
char c[100][100];
void judge(int i, int j) {
	char tmp = c[i][j];
	c[i][j] = 'X';
	if (i > 0&&c[i-1][j]==tmp)judge(i - 1, j);
	if (j > 0&&c[i][j-1]==tmp)judge(i, j - 1);
	if (i < 100&&c[i+1][j]==tmp)judge(i + 1, j);
	if (j < 100&&c[i][j+1]==tmp)judge(i, j + 1);
}
int main() {
	int h, w;
