				cin >> c[i][j];
		}
		for (int i = 0; i < w; i++) {
			for (int j = 0; j < h; j++)
				if (c[i][j] != 'X') { judge(i, j); ans++; }
		}
		cout << ans << "\n";
	} while (h != 0);
	}

