  dfs(h - 1, w, c);
  dfs(h, w + 1, c);
  dfs(h, w - 1, c);

  return;
}

int solve()
{
  int res = 0;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (!passed[i][j]) {
        res++;
        dfs(i, j, orchard[i][j]);
      }
    }
  }

  return res;
}

