    //入力作業
    int H,W;
    while(cin>>H>>W){
        if(!H&&!W)break;

        int orchard[111][111]={0};

        for(int i=1; i<=H; i++){
            for(int j=1; j<=W; j++){
                char input;
                cin>>input;
                if(input=='#'){
                    orchard[i][j]=1;
                }else if(input=='*'){
                    orchard[i][j]=2;
                }else if(input=='@'){
                    orchard[i][j]=3;
                }
            }
        }


        //入力終了
        //処理開始
        bool cheack_flag[111][111]={0};
        int ans=0;
        for(int i=1; i<=H; i++){
            for(int j=1; j<=W; j++){
                if(cheack_flag[i][j]==0&&orchard[i][j]!=0){
                    property_distribution(orchard, cheack_flag, i, j, orchard[i][j]);
                    ans++;

                    /////
                    //print_array(10, 10, cheack_flag);
                    /////
                }
            }
        }
        cout<<ans<<endl;
    }

}

