void dfs(int x,int y,char zf){
	mymap[x][y] = '.';

	for(int i=0;i<4;i++){
		int nx = x+fx[i][0];
		int ny = y+fx[i][1];
		if(0<=nx && nx<N && 0<=ny && ny<M && mymap[nx][ny] == zf){
