struct UF {
  vector<int> data;
  int group;
  UF(int size) : data(size, -1), group(size) {}
  bool merge(int x, int y){
    x = root(x), y = root(y);
    if (x != y){
      group--;
      if (data[x] > data[y]) swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
    return (x != y);
  }
  int root(int x){
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int count(){
    return group;
  }
};

