      field.push_back(s);
    }
    UF uf(h * w);
    for (int i = 0; i < h; i++){
      for (int j = 0; j < w; j++){
        for (int d = 0; d < 4; d++){
          static const int dx[] = {0, 0, 1, -1};
          static const int dy[] = {1, -1, 0, 0};
          int nx = j + dx[d];
          int ny = i + dy[d];
          if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
          if (field[i][j] == field[ny][nx]){
            uf.merge(i * w + j, ny * w + nx);
          }
        }
      }
    }
    printf("%d\n", uf.count());
  }

  return 0;
}

