  int H, W;
  while(1){
    cin >> H >> W;
    if(H == 0 && W == 0){
      break;
    }
    vector<vector<char>> p(H, vector<char>(W));
    REP(i, 0, H){
      REP(j, 0, W){
        cin >> p[i][j];
      }
    }
    int ans = solve(H, W, p);
    cout << ans << endl;
  }

  return 0;
}

