		d[a + 1][b] = 'a';
		solve(a+1,b);
	}
	if (a - 1 >= 0 && d[a - 1][b] == tmp) {
		d[a - 1][b] = 'a';
		solve(a-1,b);
	}
	if (b - 1 >= 0 && d[a][b - 1] == tmp) {
		d[a][b - 1] = 'a';
		solve(a,b-1);
	}
	return;
}
