void fillDot(vector<string> &v,int x,int y,char c){
  if(x<0||y<0||v.size()<=y||v[y].size()<=x) return;
  if(v[y][x]!=c) return;
  v[y][x]='.';
  fillDot(v,x-1,y,c);
  fillDot(v,x+1,y,c);
  fillDot(v,x,y-1,c);
  fillDot(v,x,y+1,c);
}

