void dfs(vector<vector<char>>& farm, 
        vector<vector<bool>>& searched,
        array<int,4>& dy, 
        array<int,4>& dx, 
        int h, 
        int w)
{
    if(searched[h][w]) return;

    searched[h][w] = true;

    for(int i = 0;i < 4;i++){
        if(h + dy[i] < 0 || h + dy[i] >= farm.size()) continue;
        if(w + dx[i] < 0 || w + dx[i] >= farm[0].size()) continue;
        if(searched[h + dy[i]][w + dx[i]]) continue;
        if(farm[h][w] != farm[h + dy[i]][w + dx[i]]) continue;
        dfs(farm, searched, dy, dx, h + dy[i], w + dx[i]);
    }
}

int main(){
    int H,W;
