        array<int,4> dy = {1, 0, 0, -1};
        array<int,4> dx = {0, 1, -1, 0};
        int ans = 0;

        for(int i=0;i<H;i++)for(int j=0;j<W;j++){
            cin >> farm[i][j];
        }

        for(int i=0;i<H;i++){
            for(int j=0;j<W;j++){
                if(searched[i][j]) continue;
                dfs(farm, searched, dy, dx, i, j);
                ans++;
            }
        }

        cout << ans << endl;
    }
}

