  for (int i = 0; i < H_MAX+2; i++) {
    for (int j = 0; j < W_MAX+2; j++) {
      tile[i][j] = 0;
    }
  }
  ans = 0;
}

void dfs(int n, int m) {
  char fruit = tile[n][m];
  tile[n][m] = 0;
  for (int i = -1; i < 2; i++) {
    for (int j = -1; j < 2; j++) {
      if (i * j == 0 && tile[n+i][m+j] == fruit) {
        dfs(n+i, m+j);
      }
    }
  }
}

