typedef complex<int> P;

P d[4] = {
    P(0,1),
    P(0,-1),
    P(1,0),
    P(-1,0)
};

void f(vs& g, int i, int j){
    stack<P> s;
    s.push(P(i,j));
    char init = g[i][j];
    while(s.size()){
        P t = s.top();
        s.pop();
        int x = t.imag();
        int y = t.real();
        if(x<0 || y<0 || x>=g[0].size() || y>=g.size()) continue;
        if(g[y][x]==' ') continue;
        if(g[y][x]!=init) continue;

        g[y][x] = ' ';
        rep(i,4) s.push(t+d[i]);
    }
}

