void fruit(int H,int W,char n){
  if(F[H][W]!=n){
    return;
  }

  F[H][W] = '.';

  fruit(H-1,W  ,n);
  fruit(H  ,W+1,n);
  fruit(H+1,W  ,n);
  fruit(H  ,W-1,n);
}

int main(){
  while(1){
    int N,M;
    cin >> N >> M;
    if(N==0 && M==0){
      break;
    }

    for(int y=1;y<=N;y++){
      for(int x=1;x<=M;x++){
        cin >> F[y][x];
      }
    }

    int cnt = 0;
    for(int y=1;y<=N;y++){
      for(int x=1;x<=M;x++){
        if(F[y][x]=='@'){
          cnt++;
          fruit(y,x,'@');
        }else if(F[y][x]=='#'){
          cnt++;
          fruit(y,x,'#');
        }else if(F[y][x]=='*'){
          cnt++;
          fruit(y,x,'*');
        }
      }
    }
    cout << cnt << endl;
  }

  return 0;
}

#include <iostream>

using namespace std;
char field[102][102];
int dx[4] = {-1, 0, 1,  0};
int dy[4] = { 0, 1, 0, -1};

void DFS(int y, int x, char c)
{
	field[y][x] = '.';
	for(int i = 0; i < 4; ++i)
	{
		int nx = x + dx[i];
		int ny = y + dy[i];
		if(field[ny][nx] == c)
		{
			DFS(ny, nx, c);
		}
	}
}

void solve()
{
	int H, W;
	while(cin >> H >> W, H || W)
	{
		for(int i = 1; i <= H; ++i)
		{
			for(int j = 1; j <= W; ++j)
			{
				cin >> field[i][j];
			}
		}
		int count = 0;
		for(int i = 1; i <= H; ++i)
		{
			for(int j = 1; j <= W; ++j)
			{
				if(field[i][j] != '.')
				{
					++count;
					DFS(i, j, field[i][j]);
				}
			}
		}
		cout << count << endl;
	}
}

