            break;
        gets(d[0]);
        for(int x = 0; x < X; x++){
            gets(d[x]);
            for(int y = 0; y < Y; y++){
                k[x][y] = -1;
            }
        }
        for(int x = 0; x < X; x++){
            for(int y = 0; y < Y; y++){
                if(k[x][y] != -1)
                    continue;
                search(x, y, d[x][y]);
                r++;
            }
        }
        printf("%d\n", r);
    }
    return 0;
