void dl (int x,int y,char target) {
	//cout << x << "/" << y << "/" << target << endl;
	Data[y][x] = '+';
	for (int i = -1;i < 2;i++) {
		//cout << "	" << i << "/" << Data[y][x+i] << ":";
		if (i==0) continue;
		if(x+i>=0 && x+i < W && Data[y][x+i] == target) {
			dl(x+i,y,target);
		}
		if(y+i>=0 && y+i < H && Data[y+i][x] == target) {
			dl(x,y+i,target);
		}
	}	
	return;
}
int main() {
	int ans = 0;
	for(;;) {
		cin >> H >> W;
