void dfs(int x, int y, char c) {
	board[y][x] = '.';

	for (int i = 0; i < 4; i++) {
		int nx = x + dx[i];
		int ny = y + dy[i];
		if (board[ny][nx] == c) {
			dfs(nx, ny, c);
		}
	}
}

int solve() {
	int ret = 0;
	for (int i = 1; i <= h; i++) {
		for (int j = 1; j <= w; j++) {
			if (board[i][j] == '.') {
				continue;
			}
			dfs(j, i, board[i][j]);
			ret++;
		}
	}

	return ret;
}

