using namespace std;

int main() {
    while (true) {
        int W, H;
        scanf("%d %d", &H, &W);
        if (W == 0 && H == 0) {
            return 0;
        }
        unique_ptr<char[]> field(new char[W * H]);
        for (int i = 0; i < H; i++) {
            scanf("%s", field.get()+(W*i));
        }
        vector<int> stack;
        stack.reserve(W*H);
        int count = 0;
        for (int x = 0; x < W; x++) {
            for (int y = 0; y < H; y++) {
                if (field[x+y*W] == 'X') {
                    continue;
                }
                count++;
                char fruit = field[x+y*W];
                stack.push_back(x+y*W);
                field[x+y*W] = 'X';
                while (!stack.empty()) {
                    int idx = stack.back();
                    stack.pop_back();
                    int cx = idx % W;
                    int cy = idx / W;
                    for (int dx = 0; dx < 2; dx++) {
                        for (int dy = 0; dy < 2; dy++) {
                            int nx = cx + -1 + 1*dx + 1*dy;
                            int ny = cy + 0 + (-1)*dx + 1*dy;
                            if (nx < 0 || nx >= W || ny < 0 || ny >= H) {
                                continue;
                            }
                            if (field[nx+ny*W] != fruit) {
                                continue;
                            }
                            stack.push_back(nx+ny*W);
                            field[nx+ny*W] = 'X';
                        }
                    }
                }
            }
        }
        cout << count << endl;
    }
    return 0;
}

