	while(scanf("%d %d", &H, &W) != EOF){
		if(H == 0 && W == 0) break;
		count = 0;
		for(int i = 0; i < H; i++){
			scanf("%s", table[i]);
		}
		for(int i = 0; i < H; i++){
			for(int j = 0; j < W; j++){
				if(table[i][j] == ' ') continue;
				if(table[i][j] == '@') recA(i, j);
				else if(table[i][j] == '#') recB(i, j);
				else if(table[i][j] == '*') recC(i, j);
				count++;
			}
		}

		printf("%d\n", count);
	}

	return 0;
}

