struct UnionFind{
    vector<int> par; // 親
    vector<int> rank; // 木の深さ
    int size;
    UnionFind(int n){
        REP(i,n) par.push_back(i);
        rank = vector<int>(n);
        size=n;
    }
    int root(int x){
        if(par[x] == x)return x;
        return par[x] = root(par[x]);
    }
    bool same(int x,int y){
        return root(x) == root(y);
    }
    void unite(int x,int y){
        x = root(x);y = root(y);
        if(x==y)return;
        if(rank[x] < rank[y])par[x] = y;
        else par[y] = x;
        if(rank[x] == rank[y]) rank[x]++;
        size--;
    }
};

