void Dfs(vector<vector<char> >& table, int h, int w, int x, int y) {
  char cur = table[x][y];
  table[x][y] = '.';
  for (int i = 0; i < 4; ++i) {
    int next_x = x + dir[i][0];
    int next_y = y + dir[i][1];
    if (next_x >= 0 && next_x < w
        && next_y >=0 && next_y < h
        && table[next_x][next_y] == cur) {
        Dfs(table, h, w, next_x, next_y);
    }
  }
}

