{
    visit[i][j]= true;
    if(i-1>=0&&!visit[i-1][j]&&ch[i-1][j]=='@')
        dfs1(ch,i-1,j,visit,m,n);
    if(i+1<m&&!visit[i+1][j]&&ch[i+1][j]=='@')
