    if(j+1<n&&!visit[i][j+1]&&ch[i][j+1]=='@')
        dfs1(ch,i,j+1,visit,m,n);
}
void dfs2(char ch[105][105],int i,int j,bool visit[105][105],int m,int n)
{
    visit[i][j]= true;
    if(i-1>=0&&!visit[i-1][j]&&ch[i-1][j]=='*')
        dfs2(ch,i-1,j,visit,m,n);
    if(i+1<m&&!visit[i+1][j]&&ch[i+1][j]=='*')
        dfs2(ch,i+1,j,visit,m,n);
    if(j-1>=0&&!visit[i][j-1]&&ch[i][j-1]=='*')
        dfs2(ch,i,j-1,visit,m,n);
