  if (H == 0) { return false; }
  REP(i, H) { cin >> field[i]; }
  ans = 0;
  fill(checked[0], checked[H], false);

  REP(i, H) {
    REP(j, W) {
      if (!checked[i][j]) {
        Dfs(i, j);
        ++ans;
      }
    }
  }

  cout << ans << endl;
  return true;
}

