	while (cin >> w >> h){
		if (h == 0 && w == 0)
			break;
		all.clear();
		for (int i = 0; i < h; ++i){
			string tmp;
			cin >> tmp;
			all.push_back(tmp);
		}
		solve();
	}
	return 0;
