    int res = 0;
    memset(d, INF, sizeof(d));

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (d[i][j] == INF) {
                Q q;
                q.push(P(i,j));

                d[i][j] = res;

                while (q.size()) {
                    P p = q.front(); q.pop();
                    for (int k = 0; k < 4; k++) {
