		b[x - 1][y] = 1;
		func(x - 1, y);
	}
	if (x != n1 - 1 && s[x][y] == s[x + 1][y] && b[x + 1][y] == 0) {
		b[x + 1][y] = 1;
		func(x + 1, y);
	}
	if (y != 0 && s[x][y] == s[x][y - 1] && b[x][y - 1] == 0) {
		b[x][y - 1] = 1;
		func(x, y - 1);
	}
	if (y != n2 - 1 && s[x][y] == s[x][y + 1] && b[x][y + 1] == 0) {
		b[x][y + 1] = 1;
		func(x, y + 1);
	}
	return;
}

int main() {
	while (1) {
		for (int i = 0; i < 100; i++) {
			for (int j = 0; j < 100; j++) {
				s[i][j] = '!';
				b[i][j] = 0;
				ans = 0;
			}
		}
		scanf("%d", &n1);
		scanf("%d", &n2);
		if (n1 == 0 && n2 == 0) {
			break;
		}
		if (n1 == 0 || n2 == 0) {
			continue;
		}
		for (int i = 0; i < n1; i++) {
			scanf("%s", s[i]);
		}
		for (int i = 0; i < n1; i++) {
			for (int j = 0; j < 100; j++) {
				if (s[i][j] != '@' && s[i][j] != '#' && s[i][j] != '*' && s[i][j] != '!') {
					s[i][j] = '!';
				}
			}
		}
		for (int i = 0; i < n1; i++) {
			for (int j = 0; j < n2; j++) {
				if (b[i][j] == 1) {
					continue;
				}
				b[i][j] = 1;
				ans += 1;
				func(i, j);
			}
		}
		printf("%d\n", ans);
	}
	return 0;
}

// Property Distribution
#include <iostream>
#define MAX_H   100
#define MAX_W   100
using namespace std;

int H, W;
char field[MAX_H][MAX_W];

// 現在位置(x, y)
void dfs(int x, int y) {
	char mark = field[x][y];
	// 今いるところを.に置き換える
	field[x][y] = '.';

	// 移動する4方向をループ
	for (int dx = -1; dx <= 1; dx++) {
		int nx = x + dx;
		if (0 <= nx && nx < H && field[nx][y] == mark) {
			dfs(nx, y);
		}
	}
	for (int dy = -1; dy <= 1; dy++) {
		int ny = y + dy;
		if (0 <= ny && ny < W && field[x][ny] == mark) {
			dfs(x, ny);
		}
	}
	return;
}

int main(void) {
	int count = 0;
	int i, j;
	cin >> H >> W;
	for (i = 0; i < H; i++) {
		for (j = 0; j < W; j++) {
			cin >> field[i][j];
		}
	}

	for (i = 0; i < H; i++) {
		for (j = 0; j < W; j++) {
			if (field[i][j] != '.') {
				dfs(i, j);
				count++;
			}
		}
	}
	cout << count << endl;

	return 0;
}

