	void journey(
		vector<bool>& visited,
		vector<string>& field,
		int x, int y)
	{
		if (visited[W*y + x])
			return;
		else {
			char f = field[y][x];
			visited[W*y + x] = true;
			REP(i, 4) {
				int nx = x + dx[i];
				int ny = y + dy[i];
				if (rangeCheck2D(nx, ny, W, H) and f == field[ny][nx])
					journey(visited, field, nx, ny);
			}
		}
	}

