namespace aojStartingLine {
	void aojStartingLine()
	{
		cin >> N >> K >> T >> U >> V >> L;
		vector<int> ds = INP<int>(N);

		double time = 0.0;
		int restBoostL = 0;
		int restCarrot = 0;
		int currentIndex = -1;
		REP(i, L) {
			if (restBoostL > 0) {
				time += 1.0 / (double)V;
				restBoostL--;
			}
			else
				time += 1.0 / (double)U;

			if (currentIndex == -1 and ds[0] == i + 1) {
				currentIndex = 0;
				restBoostL = T * V;
			}
			else if (currentIndex >= 0 and currentIndex < (N - 1) and ds[currentIndex + 1] == (i + 1)) {
				if (restBoostL == 0) {
					restBoostL = T*V;
				}
				else if (restCarrot < K) {
					restCarrot++;
				}
				else {
					restBoostL = T*V;
				}
				currentIndex++;
			}

			if (restBoostL == 0 and restCarrot > 0) {
				restBoostL = T * V;
				restCarrot--;
			}
		}

		cout << fixed << setprecision(10) << time << endl;
	}
}

