char F[100][100];

void DFS(int H, int W, char c){
  if(F[H][W]!=c)
    return;

  F[H][W] = '.';

  DFS(H-1, W  ,c);
  DFS(H  , W+1,c);
  DFS(H+1, W  ,c);
  DFS(H  , W-1,c);
}

int main(){
