    for(int x=1; x<=M; x++)
      cin >> F[y][x];

  int cnt = 0;
  for(int y=1; y<=N; y++)
    for(int x=1; x<=M; x++)
      if(F[y][x]!='.'){
        cnt++;
        DFS(y, x, F[y][x]);
      }
  cout << cnt << endl;

  return 0;
}

