void dfs(int x, int y, int xs, int ys, char fld[]){
    char here;
    here = fld[x+xs*y];
    fld[x+xs*y] = '.';
    for (int dx=-1; dx<=1; dx++){
        for (int dy=-1; dy<=1; dy++){
            if (dx*dy!=0) continue;
            int nx = x+dx;
            int ny = y+dy;
            if (nx < 0 || nx >= xs || ny < 0 || ny >=ys) continue;
            if (fld[nx+xs*ny]==here) dfs(nx, ny, xs, ys, fld);
        }
    }
    return;
}

