typedef long long LL;
LL pow_mod(LL a,LL b,LL m){
    LL d,t;
    d = 1;
    t = a;
    while (b > 0){
        if (b % 2 == 1)
            d = (d * t) % m;
        b /= 2;
        t = (t * t) % m;
    }
    return d;
}

