void dfs(ll x,ll y) {
    vis[x][y]=1;
    for (ll i=0;i<4;i++) {
        ll xx=x+dir[i][0];
        ll yy=y+dir[i][1];
        if (xx>0&&xx<=n&&yy>0&&yy<=n) {
