size_t num = 0;
char list[H_size][W_size];

void getNum(char(*a)[W_size], char c, size_t i, size_t j, size_t &W, size_t &H) {
	if (i < 0 || j < 0 || i >= H || j >= W || a[i][j] !=c) {
		return;
	}
	if (a[i][j] == c)
	{
		a[i][j] = '.';
		getNum(a, c, i - 1, j, W, H);
		getNum(a, c, i, j + 1, W, H);
		getNum(a, c, i + 1, j, W, H);
		getNum(a, c, i, j - 1, W, H);
		return;
	}
}

int main() {

	vector<int> result;
