int search(int h,int w){
  if(memo[h][w]==1) return 0;
  if(memo[h][w]==0)memo[h][w]=1;
  int k[4]={1,0,-1,0},vi=0;
  for(int i=0;i<4;i++){
    if(memo[h+k[i]][w+k[3-i]]==0&&hatake[h][w]==hatake[h+k[i]][w+k[3-i]]){
	search(h+k[i],w+k[3-i]);
	vi++;
    } else {
      vi++;
    }
  }
  if(vi==4){return 1;}
}

int main(){
  while(1){
    cin>>H;
    cin>>W;
