typedef pair<int, int> P;

void bfs (int curr_row, int curr_col, char p, vector <string> d, vector <vector <bool> > & used )
{
	// order up right down left
	const int dir[][2] = { { -1, 0 }, { 0, 1 }, { 1, 0 }, { 0, -1 } };
	int size = d.size();
	int len  = d[0].size();
	int k;

	queue <P> Q;
	P curr(curr_row, curr_col );
	Q.push (curr );

	int row = curr_row;
	int col = curr_col;

	while (!Q.empty() ){
		curr = Q.front(); Q.pop();
		row = curr.first;
		col = curr.second;

		used[row][col] = true;

		for (k = 0; k < 4; ++k){
			int nrow = row + dir[k][0];
			int ncol = col + dir[k][1];
			if (nrow < 0 || nrow >= size || ncol < 0 || ncol >= len ){
				continue;
			} // end if
			if (!used[nrow][ncol] && d[nrow][ncol] == p ){
				P npos (nrow, ncol);
				Q.push (npos );
			} // end if
		} // end if

	} // end for		

}

