typedef struct
{
	int y;
	int x;
	char type;
} STATE;

char grid[256][256];

void init()
{
	memset(grid, 0, sizeof(grid));
}

void search(int ny, int nx)
{
	queue<STATE> que;
	que.push({ny, nx, grid[ny][nx]});
	while (!que.empty()){
		STATE st = que.front(); que.pop();
		if (grid[st.y][st.x] == 0) continue;
		grid[st.y][st.x] = 0;

		for (int k = 0; k < 4; k++){
			int ty = st.y + dy[k];
			int tx = st.x + dx[k];

			if (grid[ty][tx] == st.type){
				que.push({ty, tx, st.type});
			}
		}
	}
}

