      cin >> g[i];
    }
    memset( d , 0 , sizeof(d) );
    int ret = 0;
    for(int i=0;i<w;i++){
      for(int j=0;j<h;j++){
	if(g[i][j] != '\0'){
	  dfs( i , j , g[i][j] );
