void dfs(int y,int x,char c){
  queue<P> que;
  que.push(P(y,x,c));
  d[y][x] = 1;
  while(!que.empty()){
    P p = que.front();que.pop();
    g[p.y][p.x] = '\0';
    for(int i=0;i<4;i++){
      int ty = p.y + dy[i];
      int tx = p.x + dx[i];
      if(g[ty][tx] == c && d[ty][tx] == 0){
	d[ty][tx] = 1;
	g[ty][tx] = '\0';
	que.push(P(ty,tx,c));
      }
    }
  }
}

