    if(F[Y][X]=='#')return;

    F[Y][X]='.';

    DFS2(Y-1,X-1);
    DFS2(Y-1,X  );
    DFS2(Y-1,X+1);
    DFS2(Y  ,X-1);
    DFS2(Y  ,X+1);
    DFS2(Y+1,X-1);
    DFS2(Y+1,X  );
    DFS2(Y+1,X+1);
}

void DFS3(int Y,int X){
    if(F[Y][X]=='*')return;

    F[Y][X]='.';

    DFS3(Y-1,X-1);
    DFS3(Y-1,X  );
    DFS3(Y-1,X+1);
    DFS3(Y  ,X-1);
    DFS3(Y  ,X+1);
    DFS3(Y+1,X-1);
    DFS3(Y+1,X  );
    DFS3(Y+1,X+1);
}

int main(){
