using namespace std;

int cnt;
int m, n;
char map[101][101];
bool vis[101][101];

struct Node {
	int x, y;
	Node () {}
	Node (int X,int Y) {
		x = X; y = Y;
	}
};

int X[] = {1, 0, -1, 0};
int Y[] = {0, -1, 0, 1};

void dfs(Node now) {
	Node nex;
	for (int i=0; i<n; i++) {
		nex = Node(now.x + X[i], now.y + Y[i]);
		if (nex.x < m && nex.x >= 0 && nex.y < n && nex.y >= 0) {
			if (vis[nex.x][nex.y] == false && map[nex.x][nex.y] == map[now.x][now.y]) {
				vis[nex.x][nex.y] = true;
				dfs(nex);
			}
		}
	}
}

int main () {
	while (cin >> m >> n) {
		if (m == 0 && n == 0) break;
		cnt = 0;
		memset(vis,false,sizeof(vis));
		for (int i=0; i<m; i++) {
			cin >> map[i];
		}
		for (int i=0; i<m; i++) {
			for (int j=0; j<n; j++) {
				if (vis[i][j] == false) {
					vis[i][j] = true;
					dfs(Node (i,j));
					cnt++;
				}
			}
		}
		cout << cnt << endl;
	}
	return 0;
}

#include <stdio.h>

int h, w;
char map[100][100];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};

void dfs(int i, int j, char tree){
  map[i][j] = '.';
  int x, y;
  for(int l = 0; l < 4; l++){
    x = j + dx[l];
    y = i + dy[l];
    if(y < h && y >= 0 && x < w &&  x >= 0 && map[y][x] == tree){
      dfs(y,x,tree);
    }
  }
  return;
}

int solve(){
  int sum = 0;
  for(int i = 0; i < h; i++){
    for(int j = 0; j < w; j++){
      if(map[i][j] != '.'){
        dfs(i, j, map[i][j]);
        sum++;
      }
    }
  }
  return sum;
}

int main(){
  while(true){
    scanf("%d %d", &h, &w);
    if(h == 0 && w == 0)
      break;
    for(int i = 0; i< h; i++){
      scanf("%s",map[i]);
    }
    printf("%d\n",solve());
  }
  return 0;
}

