{
	while (cin>>Row>>Height && Row !=0 && Height != 0)
	{
		total_type = 0;
		memset(flag_pos,true,sizeof(flag_pos[0][0]));
		for (int i=1;i<=Row;i++)
		{
			for (int j=1;j<=Height;j++)
			{
				cin>>dataSet[i][j];
				flag_pos[i][j] = false;
			}
		}
		for (int i=1;i<=Row;i++)
		{
			for (int j=1;j<=Height;j++)
			{
				if (flag_pos[i][j] == false)
				{
					if (dataSet[i][j] == '#')
					{
						count_type (i,j,'#');
						total_type++;
					}
					else if (dataSet[i][j] == '*')
					{
						count_type (i,j,'*');
						total_type++;
					}
					else if (dataSet[i][j] == '@')
					{
						count_type (i,j,'@');
						total_type++;
					}
				}
			}
		}
		cout<<total_type<<endl;
	}
	return 0;
}

