	vis[x][y] = 1;
	if (x > 0) dfs(x - 1, y, map[x][y]);
	if (x < H - 1) dfs(x + 1, y, map[x][y]);
	if (y > 0) dfs(x, y - 1, map[x][y]);
	if (y < W - 1) dfs(x, y + 1, map[x][y]);
}
