			}
		for (int i = 0; i <= H; ++i)
			for (int j = 0; j <= W; ++j)
				if (!vis[i][j])
				{
					dfs(i, j, map[i][j]);
					ans++;
				}
		cout << ans << endl;
		return 0;
	}
}

