const int margin = 2;

bool check(int i, int j, char c, char table[128][128]) {
	if(table[i + margin][j + margin] != c || c == 0) {
		return false;
	}

	table[i + margin][j + margin] = 0;
	check(i + 1, j, c, table);
	check(i - 1, j, c, table);
	check(i, j + 1, c, table);
	check(i, j - 1, c, table);

	return true;
}

