	int H,W;
	cin >> H >> W;
	if(H==0) return false;

	for(int i=0;i<H;i++){
		cin >> F[i];
	}//入力

	for(int i=0;i<H;i++){
		for(int j=0;j<W;j++){
			bool check;
			check=search(i,j,H,W,F[i][j]);
			if(check) ans[counter]++;
		}
	}
	return true;
}


int main (){
