int visit[maxn][maxn];
int total;

bool judge(int x,int y){
	if(x>=1&&x<=n&&y>=1&&y<=m)
		return true;
	return false;
} 

void dfs(int x,int y){
	for(int i=0;i<4;i++){
		int nextx = x + dx[i];
		int nexty = y + dy[i];
		if(!visit[nextx][nexty]&&judge(nextx,nexty)&&map[nextx][nexty]==map[x][y]){
			visit[nextx][nexty] = visit[x][y];
			dfs(nextx,nexty);
		}
	}
}


