char HW[101][101];

void DFS(int Y,int X,char c)
{
	if(HW[Y][X]=='0'||HW[Y][X]!=c)
		return;

	HW[Y][X]='0';

	DFS(Y-1,X,c);
	DFS(Y,X+1,c);
	DFS(Y+1,X,c);
	DFS(Y,X-1,c);
}	

