{
	if(F[X][Y]!='#')
		return;

	F[X][Y] = '.';

	DFSpersimmon(X-1,Y  );
	DFSpersimmon(X  ,Y+1);
	DFSpersimmon(X+1,Y  );
	DFSpersimmon(X  ,Y-1);
}	

void DFSorange(int X,int Y)
{
	if(F[X][Y]!='*')
		return;

	F[X][Y] = '.';

	DFSorange(X-1,Y  );
	DFSorange(X  ,Y+1);
	DFSorange(X+1,Y  );
	DFSorange(X  ,Y-1);
}	

