#define MAX_H 110
#define MAX_W 110

char field[MAX_H][MAX_W];


void dfs(int y, int x)
{
	char c = field[y][x];
	field[y][x] = 0;

	if (c == field[y][x + 1]){
		dfs(y, x + 1);
	}
	if (c == field[y][x - 1]){
		dfs(y, x - 1);
	}
	if (c == field[y + 1][x]){
		dfs(y + 1, x);
	}
	if (c == field[y - 1][x]){
		dfs(y - 1, x);
	}
}


int main(void)
{
