	if (a[i][j] == c)
	{
		a[i][j] = '.';
		getNum(a, c, i - 1, j, W, H);
		getNum(a, c, i, j + 1, W, H);
		getNum(a, c, i + 1, j, W, H);
		getNum(a, c, i, j - 1, W, H);
		return;
	}
}

