using namespace std;

typedef long long ll;
typedef pair<int,int> P;

int bfs(char** stage,int W,int H){
	int res=0;

	for(int x=0;x<W;x++){
		for(int y=0;y<H;y++){
			if(stage[y][x]=='x') continue;
			res++;
			char fruit = stage[y][x];
			queue<P> que;
			que.push(P(x,y));

			while(!que.empty()){
				int sx = que.front().first;
				int sy = que.front().second;
				que.pop();
				stage[sy][sx] = 'x';

				for(int i=-1;i<=1;i++){
					for(int j=-1;j<=1;j++){
						if(i*j!=0 || (i==j && j==0)) continue;
						int dx = sx+i;
						int dy = sy+j;

						if(dx<0 || dx>=W || dy<0 || dy>=H) continue;

						if(stage[dy][dx]!=fruit || stage[dy][dx]=='x') continue;
						que.push(P(dx,dy));
					}
				}
			}

		}

	}

	return res;
}

int main(){
	string str;
	while(getline(cin,str)){
		int W,H;		
		sscanf(str.c_str(),"%d %d",&H,&W);
		if(H==W && W==0) break;

		char** stage = new char*[H];
		for(int i=0;i<H;i++){
			stage[i] = new char[W];
		}

		for(int i=0;i<H;i++){
			getline(cin,str);
			for(int j=0;j<W;j++){
				stage[i][j] = str[j];
			}
		}

		cout << bfs(stage,W,H) << endl;

		for(int i=0;i<H;i++){
			delete[] stage[i];
		}
		delete[] stage;
	}
}

