string field[100];
bool used[100][100];
int dxy[] = {0,1,0,-1};
int h, w;

void dfs(int y, int x) {
    if (used[y][x]) return;
    used[y][x] = true;
    int i;
    REP (i,4) {
        int ny = y + dxy[i];
        int nx = x + dxy[(i+1)%4];
        if (ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
        if (field[ny][nx] == field[y][x]) dfs(ny,nx);
    }
}

int main(void) {
