				a[i][j]=1;
				while(!q.empty()){
					auto p=q.front();
					q.pop();
					ll y=p.first;
					ll x=p.second;
					rep(k,4){
						ll ny=y+dy[k];
						ll nx=x+dx[k];
						if(ny<0 || ny>=h || nx<0 || nx>=w) continue;
						if(c[y][x]==c[ny][nx] && a[ny][nx]==0){
							a[ny][nx]=1;
							q.push({ny,nx});
						}
					}
				}
				ans++;
			}
		}
		cout << ans << endl;
	}
	return 0;
}

