            }
        }

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (flag[i][j]) {
                    count++;
                    // cout << "f : " << i << "," << j << endl;
                    solve(j, i, tile, H, W, flag);
                }
            }
        }

        cout << count << endl;
    }

}

