inline int nextChar(void){
	char ch=getchar();
	while(ch!='#'&&ch!='*'&&ch!='@')
		ch=getchar();
	return ch;
}
inline void putInt(int tmp){
	int stk[10],tail=0;
	while(tmp)
		stk[tail++]=tmp%10,tmp/=10;
	for(int i=tail-1;i>=0;i--)
		putchar('0'+stk[i]);
	puts("");
}
