  for (int dy = -1; dy <= 1; dy++) {
    if(dy == -1 || dy == 1){
      int dx = 0;
      int nx = x + dx, ny = y + dy;
      if (0 <= nx && nx < W && 0 <= ny && ny < H && farms[nx][ny] == f){
        dfs(nx, ny);
      }
    }
    if (dy == 0){
      for (int dx = -1; dx <= 1; dx = dx + 2) {
        int nx = x + dx, ny = y + dy;
        if (0 <= nx && nx < W && 0 <= ny && ny < H && farms[nx][ny] == f){
          dfs(nx, ny);
        }
      }
    }
  }
  return ;
}


