P now;
char field[MAX_H][MAX_W+1];
int dx[4]={0,1,0,-1},dy[4]={1,0,-1,0};

void dfs(int x,int y){

    fields.push(P(x,y));

    while(!fields.empty()){
        now=fields.top();
        fields.pop();
        x=now.first; y=now.second;
    //  cout<<x<<','<<y<<endl;
        for(int i=0;i<4;i++){
            int nx=x+dx[i]; int ny=y+dy[i];
            if(0<=nx&&nx<h&&0<=ny&&ny<w&&field[nx][ny]!='%'&&field[x][y]==field[nx][ny]){
                fields.push(P(nx,ny));
            }
        }
        field[x][y]='%';
    }

    return;
}

