#include <cstdio>

using namespace std;

char a[101][101];
int h, w;

void fill(char c, int x, int y) {
    a[x][y] = 'x';
    if (x + 1 < w  && a[x + 1][y] == c) fill(c, x + 1, y);
    if (0 <= x - 1 && a[x - 1][y] == c) fill(c, x - 1, y);
    if (y + 1 < h  && a[x][y + 1] == c) fill(c, x, y + 1);
    if (0 <= y - 1 && a[x][y - 1] == c) fill(c, x, y - 1);
}

int main(void) {
    while (true) {
        scanf("%d %d", &h, &w);
        if (h == 0 && w == 0) break;
        for (int i = 0; i < h; i++) {
            scanf("%s", a[i]);
        }
        int n = 0;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (a[i][j] != 'x') {
                    fill(a[i][j], i, j);
                    n++;
                }
            }
        }
        printf("%d\n", n);
    }
    return 0;
}

#include <iostream>

using namespace std;

int dir[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
char table[100][100];

void Dfs(int h, int w, int x, int y) {
  char cur = table[x][y];
  table[x][y] = 'X';
  for (int i = 0; i < 4; ++i) {
    int next_x = x + dir[i][0];
    int next_y = y + dir[i][1];
    if (next_x >= 0 && next_x < w
        && next_y >=0 && next_y < h
        && table[next_x][next_y] == cur) {
        Dfs(h, w, next_x, next_y);
    }
  }
}

int main() {
  int h, w;
  while (cin >> h >> w, w > 0) {
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        cin >> table[i][j];
      }
    }
    int ret = 0;
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        if (table[i][j] != 'X') {
          Dfs(h, w, i, j);
          ++ret;
        }
      }
    }
    cout << ret << endl;
  }
  return 0;
}

