vector<string> vs;

int dfs(int y, int x, char c){
    int ret = 0;
    if(y < 0 || y >= H || x < 0 || x >= W) return ret;
    if(visited[y][x]) return ret;
    if(c!=vs[y][x]) return ret;
    char now = vs[y][x];
    ret++;
    visited[y][x] = true;
    ret += dfs(y+1, x, now);
    ret += dfs(y-1, x, now);
    ret += dfs(y, x+1, now);
    ret += dfs(y, x-1, now);
    return ret;
}

