int main() {
  char ch;
  while (cin >> H >> W, H+W) {
    // grid, visited初期化
    rep(i, 0, H) {
      rep(j, 0, W) {
        cin >> ch;
        if (ch == '#') {
          grid[i][j] = 0;
        } else if (ch == '*') {
          grid[i][j] = 1;
        } else {
          grid[i][j] = 2;
        }
        visited[i][j] = false;
      }
