        }

        char input[102][102];
        int table[102][102];
        for (int i=0; i<102; i++) {
            for (int j=0; j<102; j++) {
                input[i][j] = '\0';
                table[i][j] = 0;
            }
        }
        for (int i=1; i<height+1; i++) {
