void mark(char input[][102], int table[][102], int i, int j){
    if (table[i][j] != 0) {
        return;
    }
    char typeOfTree;
    typeOfTree = input[i][j];
    table[i][j] = ans;
    if (typeOfTree == input[i-1][j]) {
        mark(input, table, i-1, j);
    }
    if (typeOfTree == input[i][j-1]) {
        mark(input, table, i, j-1);
    }
    if (typeOfTree == input[i][j+1]) {
        mark(input, table, i, j+1);
    }
    if (typeOfTree == input[i+1][j]) {
        mark(input, table, i+1, j);
    }
}

