	DFS(j,i,h,w,key);
      }
    }
  }

  return cnt;
}


void DFS(int x,int y,int h,int w,char key){

  if(x<0 || y<0 || x>=w || y>=h) return;
  if(map[y][x] != key) return;

  map[y][x]='0';

  DFS(x+1,y,h,w,key); DFS(x,y+1,h,w,key);
  DFS(x-1,y,h,w,key); DFS(x,y-1,h,w,key);

  return;
}

