}
void DFSP(int y,int x){
	if(F[y][x]!='#')
		return;
	F[y][x]='.';
	DFSP(y-1,x  );
	DFSP(y  ,x+1);
	DFSP(y+1,x  );
	DFSP(y  ,x-1);
}
void DFSO(int y,int x){
	if(F[y][x]!='*')
		return;
	F[y][x]='.';
	DFSO(y-1,x  );
	DFSO(y  ,x+1);
	DFSO(y+1,x  );
	DFSO(y  ,x-1);
}
