int check(int x,int y,char ch)
{
    if(x>=0 && x<n && y>=0 && y<m && Map[x][y]==ch && !vis[x][y] && (ch=='@' ||ch=='#' || ch=='*'))
        return 1;
    return 0;
}

void dfs(int x,int y,char ch)
{
    for(int i=0;i<4;i++)
    {
        int new_x = x + dir[i][0];
        int new_y = y + dir[i][1];
        if(check(new_x,new_y,ch))
        {
            vis[new_x][new_y] = 1;
            dfs(new_x,new_y,ch);
        }
    }
    return;
}

