string s[1000];
int n,m,memo[1000][1000];

int solve(int i, int j){

  if(memo[i][j] > 0) return memo[i][j];
  memo[i][j] = 1;

  if(i + 1 < n && s[i + 1][j] == s[i][j]) solve(i + 1,j);
  if(j + 1 < m && s[i][j + 1] == s[i][j]) solve(i,j + 1);
  if(i - 1 > -1 && s[i - 1][j] == s[i][j]) solve(i - 1,j);
  if(j - 1 > -1 && s[i][j - 1] == s[i][j]) solve(i,j - 1);

  return 0;
}


