void fill(int row, int col) {
	char type = blocks[row][col];
	blocks[row][col] = '.';

	int di[] = {1, -1, 0, 0};
	int dj[] = {0, 0, 1, -1};

	for (int k = 0; k < 4; k++) {
		int ti = row + di[k];
		int tj = col + dj[k];

		if (ti < 0 || tj < 0 || ti >= H || tj >= W) continue;
		if (blocks[ti][tj] == type) {
			fill(ti, tj);
		}
	}
}

