	int ans = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (blocks[i][j] != '.') {
				fill(i, j);
				ans++;
			}
		}
	}
	printf("%d\n", ans);
}

int main() {
	while (!init()) {
		solve();
