void serch(int x, int y, int H, int W, char f) {
	if(0 <= x && x < H && 0 <= y && y < W && !serchFlag[x][y] && mp[x][y] == f) {
		serchFlag[x][y] = 1;
		serch(x + 1, y, H, W, f);
		serch(x - 1, y, H, W, f);
		serch(x, y + 1, H, W, f);
		serch(x, y - 1, H, W, f);
	}
}
int solve(int H, int W) {
	int i, j, num;
	for(i = 0; i < H; ++ i) for(j = 0; j < W; ++ j) serchFlag[i][j] = 0;
	num = 0;
	for(i = 0; i < H; ++ i) {
		for(j = 0; j < W; ++ j) {
			if(!serchFlag[i][j]) {
				serch(i, j, H, W, mp[i][j]);
				num ++;
			}
		}
	}
	return num;
}
