char room[100][100];
char visited = 'v';
int dirs[4][2] = {
    {-1, 0},
    {1, 0},
    {0, 1},
    {0, -1}};

void dfs(char room[100][100], char current, int h, int w, int i, int j)
{
  if (i < 0 || i >= h || j < 0 || j >= w || room[i][j] != current)
  {
    return;
  }
  room[i][j] = visited;
  for (int k = 0; k < 4; k++)
  {
    dfs(room, current, h, w, i + dirs[k][0], j + dirs[k][1]);
  }
}

