}

typedef struct { char r, c; } T;
char a[103][103];
char f[103][103];
T s[10004];
int top;

void see(int r, int c, char k, int n)
{
	//	printf("See [%d,%d], n=%d\n", r, c, n);
	f[r][c] = n, s[0].r = r, s[0].c = c;
	for (top = 1; top; ) {
		r = s[--top].r, c = s[top].c;
		if (a[r - 1][c] == k && !f[r - 1][c]) f[r - 1][c] = n, s[top].r = r - 1, s[top++].c = c;
		if (a[r + 1][c] == k && !f[r + 1][c]) f[r + 1][c] = n, s[top].r = r + 1, s[top++].c = c;
		if (a[r][c - 1] == k && !f[r][c - 1]) f[r][c - 1] = n, s[top].r = r, s[top++].c = c - 1;
		if (a[r][c + 1] == k && !f[r][c + 1]) f[r][c + 1] = n, s[top].r = r, s[top++].c = c + 1;
	}
}

