#include <stdio.h>
#include <stdlib.h>
#include <conio.h>

void a(char c, char map[101][101], int i, int j, int H, int W) {
	if (c == map[i][j]) map[i][j] = '0';
	if (i+1 < H && map[i+1][j] == c) a(c,map,i+1,j,H,W);
	if (j+1 < W && map[i][j+1] == c) a(c,map,i,j+1,H,W);
	if (i-1 >= 0 && map[i-1][j] == c) a(c,map,i-1,j,H,W);
	if (j-1 >= 0 && map[i][j-1] == c) a(c,map,i,j-1,H,W);
}

int main() {
	int out, H, W, i, j;
	char map[101][101];
	while (1) {
		out = 0;
		scanf("%d%d", &H, &W);
		if (H == W && H == 0) break;
		for (i=0; i < H ;i++) {
			for (j=0; j < W ;j++) {
				scanf("%c", &map[i][j]);
				if (map[i][j] == '\n') {
					scanf("%c", &map[i][j]);
				}
			}
		}
		for (i=0; i < H ;i++) {
			for (j=0; j < W ;j++) {
				if (map[i][j] != '0') {
					a(map[i][j], map, i, j, H, W);
					out++;
				}
			}
		}
		printf("%d\n", out);
	}
	return 0;
}

#include <stdio.h>
struct place{
    int x;
    int y;
};
void serch(char line[][101],struct place map,char sign){
    line[map.y][map.x]='%';
    struct place temp;
    if(line[map.y][map.x+1] == sign){
        line[map.y][map.x+1]='%';
        temp.x=map.x+1;
        temp.y=map.y;
        serch(line,temp,sign);
    }
    if(line[map.y+1][map.x] == sign){
        line[map.y+1][map.x]='%';
        temp.x=map.x;
        temp.y=map.y+1;
        serch(line,temp,sign);
    }
    if(map.x != 0){
        if(line[map.y][map.x-1] == sign){
            line[map.y][map.x-1]='%';
            temp.x=map.x-1;
            temp.y=map.y;
            serch(line,temp,sign);
        }
    }
    if(map.y != 0){
        if(line[map.y-1][map.x] == sign){
            line[map.y-1][map.x]='%';
            temp.x=map.x;
            temp.y=map.y-1;
            serch(line,temp,sign);
        }
    }
}
int main(void){
    int n,m,sum,i,o,sign,l,q;
    while(1){
        char line[101][101]={0};
        struct place p;
        scanf("%d %d",&n,&m);
        if(n == 0)
            break;
        sum=0;
        for(i=0;i<n;i++){
            scanf("%s",line[i]);
        }
        for(i=0;i<n;i++){
                for(o=0;o<m;o++){
                    if(line[i][o] != '%'){
                        p.x=o;
                        p.y=i;
                        serch(line,p,line[i][o]);
                        sum++;
                    }
                }
        }
        printf("%d\n",sum);
    }
    return 0;
}

