void searchdel(int w,int h,int mp[100][100],int y,int x){
  int res;
  res=mp[y][x];
  mp[y][x]=0;
  if(y>0&&mp[y-1][x]==res)searchdel(w,h,mp,y-1,x);
  if(y<h-1&&mp[y+1][x]==res)searchdel(w,h,mp,y+1,x);
  if(x>0&&mp[y][x-1]==res)searchdel(w,h,mp,y,x-1);
  if(x<w-1&&mp[y][x+1]==res)searchdel(w,h,mp,y,x+1);
}


int search(int w,int h,int mp[100][100]){
  int i,j,res;
  res=0;
  for(i=0;i<h;i++){
    for(j=0;j<w;j++){
      if(mp[i][j]){
        res++;
        searchdel(w,h,mp,i,j);
      }
    }
  }
  return res;
}


