		if (H == 0 && W == 0){
			break;
		}

		//

		for (i = 0; i < H; i++){
			for (j = 0; j < W; j++){
				area_id[i][j] = i * H + j;
			}
		}

		for (i = 0; i < 128; i++){
			for (j = 0; j < 128; j++){
				area_num[i * 128 + j] = 0;
			}
		}

		cnt = 0;

		//

		for (i = 0; i < H; i++){
			scanf("%s", str[i]);
		}

		for (i = 0; i < H; i++){
			for (j = 0; j < W; j++){
				DFS(i, j, H, W);
			}
		}

		for (i = 0; i < H; i++){
			for (j = 0; j < W; j++){
				area_num[area_id[i][j]] = 1;
			}
		}

		for (i = 0; i < H; i++){
			for (j = 0; j < W; j++){
				if (area_num[i * H + j] == 1){
					cnt++;
				}
			}
		}

		printf("%d\n", cnt);
	}

	return (0);
	}

