        field[x][y] = '.';
        if (0 <= x-1 && x-1 < H && field[x-1][y] == '*') dfs(x-1, y);
        if (0 <= x+1 && x+1 < H && field[x+1][y] == '*') dfs(x+1, y);
        if (0 <= y-1 && y-1 < W && field[x][y-1] == '*') dfs(x, y-1);
        if (0 <= y+1 && y+1 < W && field[x][y+1] == '*') dfs(x, y+1);
    } 
    if (field[x][y] == '@') {
        field[x][y] = '.';
        if (0 <= x-1 && x-1 < H && field[x-1][y] == '@') dfs(x-1, y);
        if (0 <= x+1 && x+1 < H && field[x+1][y] == '@') dfs(x+1, y);
