  )
{
  int i, j;

  for ( ; ; )
  {
    int res;

    scanf ( " %d %d", &h, &w );
    if ( !( w | h ) ) break ;

    for ( i = 0; i < h; ++i )
    for ( j = 0; j < w; ++j )
    {
      scanf ( " %c", &d[ i ][ j ] );
    }

    for ( i = 0; i < h; ++i )
    for ( j = 0; j < w; ++j )
    {
      if ( d[ i ][ j ] == ' ' ) continue ;
      nekomimi ( j, i, d[ i ][ j ] );
      ++res;
    }

    printf ( "%d\n", res );
  }

  return ( 0 );
}

