#define MAX 101

int fillnum( char table[MAX][MAX], int i, int j, int h, int w, char c )
{
	if ( i > h || j > w || i < 0 || j < 0 ) {
		return 0;
	}

	if ( table[i][j] != c ) { return 0; } 

	table[i][j] = 0;

	fillnum( table, i-1, j, h, w, c );
	fillnum( table, i, j-1, h, w, c );
	fillnum( table, i+1, j, h, w, c );
	fillnum( table, i, j+1, h, w, c );

	return 0;
}


int search( char table[MAX][MAX], int h, int w )
{
	int num = 0;
	for ( int i = 0 ; i < h ; i++ ) {
		for ( int j = 0 ; j < w ; j++ ) {
			if ( table[i][j] == 0 ) {
				continue;
			} else {
				fillnum( table, i, j, h, w, table[i][j] );
				num++;
			}
		}
	}
	return num;
}

