#include <stdio.h>

char str[128][128];
int area_id[128][128];

void DFS(int i, int j, int H, int W){
	if (str[i][j] == str[i+1][j] && area_id[i+1][j] == (i + 1) * H + j){
		area_id[i+1][j] = area_id[i][j];
		DFS(i + 1, j, H, W);
	}
	if (str[i][j] == str[i-1][j] && area_id[i-1][j] == (i - 1) * H + j){
		area_id[i-1][j] = area_id[i][j];
		DFS(i + 1, j, H, W);
	}
	if (str[i][j] == str[i][j+1] && area_id[i][j+1] == i * H + (j + 1)){
		area_id[i][j+1] = area_id[i][j];
		DFS(i, j + 1, H, W);
	}
	if (str[i][j] == str[i][j-1] && area_id[i][j-1] == i * H + (j - 1)){
		area_id[i][j-1] = area_id[i][j];
		DFS(i, j - 1, H, W);
	}
}


