#include <stdio.h>
#include <stdlib.h>

int dfs(char **map,int **check,int i,int j,int h){
	int res=1;
	check[i][j]=2;
	if(map[i][j+1]==map[i][j] && check[i][j+1]==1)return 0;
	if(map[i][j+1]==map[i][j] && check[i][j+1]==2)return 1;
	if(map[i][j+1]==map[i][j] && check[i][j+1]==0){
		if(map[i][j+1]=='\n')return 0;
		else res*=dfs(map,check,i,j+1,h);
	}
	if(i+1>=h)return res;
	if(map[i+1][j]==map[i][j] && check[i+1][j]==0){
		res*=dfs(map,check,i+1,j,h);
	}
	return res;
}

