#define MAX 100
char farm[MAX][MAX];

void divide(int i, int j, int H, int W, char moji)
{
    if( farm[i][j] == moji ){
        farm[i][j] = '+';
        if( j + 1 < W ) divide(i, j + 1, H, W, moji);
        if( i + 1 < H ) divide(i + 1, j, H, W, moji);
        if( j - 1 >= 0 )divide(i, j - 1, H, W, moji);
        if( i - 1 >= 0 )divide(i - 1, j, H, W, moji);
    }
}

int main()
{
    int H, W, i, j, cnt;
    while(1){
