void func(int **a, int n, int m, int i, int j, int v)
{
	if(a[i][j] != v){
		return ;
	}
	a[i][j] = 0;

	if(i-1 >= 0){
		func(a, n, m, i-1, j, v);
	}
	if(i+1 < n){
		func(a, n, m, i+1, j, v);
	}
	if(j-1 >= 0){
		func(a, n, m, i, j-1, v);
	}
	if(j+1 < m){
		func(a, n, m, i, j+1, v);
	}

	return ;
}

int main(int argc, char **argv)
{
	char w;
	int **a, n, m, i, j, c;

	while(1){
		scanf("%d %d", &n, &m);
		if(n == 0){
			break;
		}
		scanf("%c", &w);
		a = (int **)calloc(n, sizeof(int));
		for(i = 0; i < n; i++){
			a[i] = (int *)calloc(m, sizeof(int));
			for(j = 0; j <= m; j++){
				scanf("%c", &w);
				if(w == '#'){
					a[i][j] = 1;
				} else if(w == '@'){
					a[i][j] = 2;
				} else if(w == '*'){
					a[i][j] = 3;
				}
			}
		}

		for(i = 0, c = 0; i < n; i++){
			for(j = 0; j < m; j++){
				if(a[i][j] != 0){
					func(a, n, m, i, j, a[i][j]);
					c++;
				}
			}
		}
		printf("%d\n", c);

		for(i = 0; i < n; i++){
			free(a[i]);
		}
		free(a);
	}

	return 0;
}

