	map[y][x]='.';
	if(y<ymax-1 && map[y+1][x]==current)gotonext(map,x,y+1,xmax,ymax);
	if(y>0 && map[y-1][x]==current)gotonext(map,x,y-1,xmax,ymax);
	if(x<xmax-1 && map[y][x+1]==current)gotonext(map,x+1,y,xmax,ymax);
	if(x>0 && map[y][x-1]==current)gotonext(map,x-1,y,xmax,ymax);
}

