#include <stdio.h>

#define N 100

static int  w;
static int  h;
static char d[ N ][ N ];

static void
nekomimi (
  int   x,
  int   y,
  char  ch
  )
{
  if ( x >= w
    || y >= h
    || d[ y ][ x ] != ch ) return ;

  d[ y ][ x ] = ' ';
  nekomimi ( x - 1, y, ch );
  nekomimi ( x + 1, y, ch );
  nekomimi ( x, y - 1, ch );
  nekomimi ( x, y + 1, ch );

  return ;
}

/** Application main entry point. */
int
main (
  int     argc,
  char  * argv[ ]
  )
{
  int i, j;

