    for ( i = 0; i < h; ++i )
    for ( j = 0; j < w; ++j )
    {
      scanf ( " %c", &d[ i ][ j ] );
    }

    for ( i = 0; i < h; ++i )
    for ( j = 0; j < w; ++j )
    {
      if ( d[ i ][ j ] == ' ' ) continue ;
      nekomimi ( j, i, d[ i ][ j ] );
