	public Main(){
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		char[][] field = new char[h+2][w+2];
		for(int i=1;i<=h;i++){
			String line = sc.next();
			for(int j=1;j<=w;j++){
				field[i][j] = line.charAt(j-1);
			}
		}
		for(int i=0;i<h+2;i++){
			field[0][i]=' ';
			field[h+1][i] = ' ';
			field[i][0] = ' ';
			field[i][w+1] = ' ';
		}

		solve(h, w, field);
	}

	private void solve(int h, int w, char[][] field){
		int res = 0;
		for(int i=1;i<=h;i++){
			for(int j=1;j<=w;j++){
				if(field[i][j]!=' '){
					res++;
					rec(field, j, i);
				}
			}
		}

		System.out.println(res);
	}

	int[] dx = {-1, 0, 1, 0};
	int[] dy = {0, -1, 0, 1};
	private void rec(char[][] field, int x, int y){
		char cur = field[y][x];
		field[y][x]=' ';

		for(int i=0;i<4;i++){
			int nx = x+dx[i];
			int ny = y+dy[i];
			if(field[ny][nx]==cur){
				rec(field, nx, ny);
			}
		}
	}
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class Main {

	public static class Point{
		public int x,y;

		Point(int x, int y){
			this.x = x;
			this.y = y;
		}
	}

	public static void main(String[] args){

		Scanner sc = new Scanner(System.in);

		while(true){
			int H = sc.nextInt();
			int W = sc.nextInt();

			if(H == 0 && W == 0){
				break;
			}

			char[][] input = new char[H][W];
			for(int i = 0; i < H; i++){
				char[] tmp = sc.next().toCharArray();
				for(int j = 0; j < W; j++){
					input[i][j] = tmp[j];
				}
			}

			boolean[][] reached = new boolean[H][W];
			for(int i = 0; i < H; i++){
				for(int j = 0; j < W; j++){
					reached[i][j] = false;
				}
			}

			int count = 0;
			for(int i = 0; i < H; i++){
				for(int j = 0; j < W; j++){
					if(reached[i][j] == false){
						count++;

						Queue<Point> queue = new LinkedList<Point>();
						queue.add(new Point(j,i));

						while (!queue.isEmpty()) {
							Point p = queue.poll();
							final int x = p.x;
							final int y = p.y;

							reached[y][x] = true;

							if (x != 0 && input[y][x] == input[y][x - 1]
									&& reached[y][x - 1] == false) {
								queue.add(new Point(x-1,y));
							}

							if (y != 0 && input[y][x] == input[y - 1][x]
									&& reached[y - 1][x] == false) {
								queue.add(new Point(x,y-1));
							}

							if (x != W - 1 && input[y][x] == input[y][x + 1]
									&& reached[y][x + 1] == false) {
								queue.add(new Point(x+1,y));
							}

							if (y != H - 1 && input[y][x] == input[y + 1][x]
									&& reached[y + 1][x] == false) {
								queue.add(new Point(x,y+1));
							}
						}
					}
				}
			}

			System.out.println(count);
		}

		return;
	}

}

