public class Main {
	final char MARK = '+';
	Scanner sc;
	int w ;
	int h;
	char [][] list;

	private void solve(int x, int y, int patMark){
		if(list[y][x] != patMark){
			return;
		}
		else{
			list[y][x] = MARK;
			solve(x-1, y, patMark);
			solve(x, y-1, patMark);
			solve(x+1, y, patMark);
			solve(x, y+1, patMark);
			return ;
		}
	}

	private void set(){
		for(int i=1; i < h + 1; i++){
			String str = sc.next();
			for(int j=0; j < w;j++){
				list[i][j+1] = str.charAt(j);
			}
		}
		//set a flame
		for(int i=0; i < w + 2; i++){
			list[0][i] = MARK;
			list[h+1][i] = MARK;
		}
		for(int i=0; i < h + 2; i++){
			list[i][0] = MARK;
			list[i][w+1] = MARK;
		}
	}

