import java.util.Scanner;

public class Main {

	//declare
	private static int         h,w,num;
	private static char   [][] orchard;
	private static boolean[][] map;

	public static void main(String[] args) {

		String[] s;

        //input
        Scanner sc = new Scanner(System.in);
        while(true){
        	s = sc.nextLine().split("\\s");
        	h = Integer.parseInt(s[0]);
        	w = Integer.parseInt(s[1]);
        	if(h+w==0){break;}
        	orchard = new char   [h][w];
        	map     = new boolean[h][w];
        	for(int i=0;i<h;i++){
       			orchard[i] = sc.nextLine().toCharArray();
        	}

        	//calculate
        	num = 0;
        	for(int i=0;i<h;i++){
        		for(int j=0;j<w;j++){
        			if(!map[i][j]){
        				num++;
        				DFS(i,j,orchard[i][j]);
        			}
        		}
        	}

        	//output
        	System.out.println(num);
        }
	}

	public static void DFS(int x,int y,char c){
		if(c != orchard[x][y] || map[x][y]){return;}
		map[x][y] = true;
		if(x-1 >= 0){DFS(x-1,y,c);}
		if(y-1 >= 0){DFS(x,y-1,c);}
		if(x+1 <  w){DFS(x+1,y,c);}
		if(y+1 <  h){DFS(x,y+1,c);}
	}
}

import java.util.Scanner;

class Main{

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		while (true) {
			int W = in.nextInt();
			int H = in.nextInt();

			char[][] map = new char[H][W];
			if (W == 0 && H == 0)
				break;

			for (int i = 0; i < H; i++) {
				char[] ss = in.next().trim().toCharArray();
				for (int j = 0; j < W; j++) {
					map[i][j] = ss[j];
				}
			}
			System.out.println(solve(map));
		}
		in.close();
	}

	private static int solve(char[][] map){

		int row = map.length;
		int col = map[0].length;

		int count = 0;
		for (int i = 0; i < row; i++) {
			for (int j = 0; j < col; j++) {
				if (map[i][j] != '.'){
					count ++;
					dfs(map, i, j, map[i][j]);
				}
			}
		}

		return count;
	}

	private static void dfs(char[][] map, int i, int j, char c){
		map[i][j] = '.';
		int row = map.length;
		int col = map[0].length;
		int[][] directions = {{-1,0},{1,0},{0,1},{0,-1}};

		for (int d = 0; d < 4; d++){
			int x = i + directions[d][0];
			int y = j + directions[d][1];

			if (x >= 0 && x < row && y >= 0 && y < col && map[x][y] == c){
				dfs(map, x, y, c);
			}
		}
	}

}

import java.util.*;

public class Main {

    static char[][] field;
    static int h, w;

    static void Erase(int i, int j) {
        char nowchar = field[i][j];
        field[i][j] = 'x'; 

        if ( i < h - 1 && field[i+1][j] == nowchar ) Erase(i+1, j); 
        if ( i > 0 && field[i-1][j] == nowchar ) Erase(i-1, j);
        if ( j < w - 1 && field[i][j+1] == nowchar ) Erase(i, j+1);
        if ( j > 0 && field[i][j-1] == nowchar ) Erase(i, j-1);

    }

    public static void main (String [] args) {

        Scanner sc = new Scanner(System.in);

        while (true) {
            h = sc.nextInt();
            w = sc.nextInt();

            if (h == 0 && w == 0)   break;

            field = new char[h][w];

            for(int i = 0; i < h; i++) {
                field[i] = sc.next().toCharArray();
            } 

            int result = 0;

            for(int i = 0; i < h; i++) {
                for(int j = 0; j < w; j++) {
                    if (field[i][j] != 'x') {
                        Erase(i, j);
                        result += 1;
                    }
                }
            }

            System.out.println(result);

        }
    }
}

import java.io.*;
