import java.util.*;
public class Main{
  static Scanner sc = new Scanner(System.in);
  static char [][] map;
  static char tmp_fruit;
  static int [] dx = {0, -1, 0, 1}, dy = {1, 0, -1, 0};
  static int H;
  static int W;
  static int ans;

  public static void main(String [] args){
    while(solve()){
      System.out.println(ans);
    }
  }

  static boolean solve(){
    H = sc.nextInt();
    W = sc.nextInt();
    if(H == 0 && W == 0)return false;
    readMap();
    for(int i = 0; i < H; i++){
      for(int j = 0; j < W; j++){
        dfs(j, i, 0);
      }
    }
    return true;
  }
  static void dfs(int x, int y, int node){
    if(map[y][x] == '.') return;
    tmp_fruit = map[y][x];
    map[y][x] = '.';
    for(int i = 0; i < dx.length ; i++){
      if(check(x + dx[i], y + dy[i])){
        if(map[y + dy[i]][x + dx[i]] == tmp_fruit){
          dfs(x + dx[i], y + dy[i], node + 1);
        }
      }
    }
    if(node == 0){
      ans++;
    }
    return;
  }

  static boolean check(int x, int y){
    if(x < 0 || W <= x || y < 0 || H <= y) return false;
    else return true;
  }

  static void readMap(){
    map = new char[H][W];
    for(int i = 0; i < H; i++){
      map[i] = sc.next().toCharArray();
    }
    return;
  }

}

import java.io.*;
public class Main{
    public static void main(String args[]){
		Main a = new Main();
		a.run();
    }

    String[][] map;
    int H = -1;
	int W = -1;

    public void run(){
        try{
            BufferedReader stdReader = new BufferedReader(new InputStreamReader(System.in));
            String line = "";
            int tempH = 0;

            while(!(line = stdReader.readLine()).equals("0 0")){
                if(W==-1){
                    H = Integer.valueOf(line.split(" ")[0]);
                    W = Integer.valueOf(line.split(" ")[1]);
                    map = new String[H][W];
                }else if(!line.equals("0 0")){
                    setLine(tempH, line);
                    tempH += 1;
                }				
				if(tempH == H){
					solve();
					W = -1;
					H = -1;
					tempH = 0;
				}
            }
            stdReader.close();
        }catch(Exception e){
			e.getStackTrace();
        }
    }

    private void solve(){
        int person = 0;
        int[] point;
		for(int i = 0; i < H; i++){
			for(int j = 0; j < W; j++){
				if(!map[i][j].equals("_")){
					int[] in = {i,j};
					search(in);
					person++;
				}
			}
		}
        System.out.println(person);
    }

    private void search(int[] point){
        int x = point[0];
        int y = point[1];
        String temp = map[x][y];
		map[x][y] = "_";

		if(x+1<H){
			if(map[x+1][y].equals(temp)&&!map[x+1][y].equals("_")){
				int[] neoPoint = {x+1, y};
				search(neoPoint);
			}
		}
		if(y+1<W){
			if(map[x][y+1].equals(temp)&&!map[x][y+1].equals("_")){
				int[] neoPoint = {x, y+1};
				search(neoPoint);
			}
		}
		if(x-1>=0){
			if(map[x-1][y].equals(temp)&&!map[x-1][y].equals("_")){
				int[] neoPoint = {x-1, y};
				search(neoPoint);
			}
		}
		if(y-1>=0){
			if(map[x][y-1].equals(temp)&&!map[x][y-1].equals("_")){
				int[] neoPoint = {x, y-1};
				search(neoPoint);
			}
		}
    }

    private void setLine(int tempH, String input){
        for(int i = 0; i < map[tempH].length; i++){
            String entity = input.substring(i,i+1);
            map[tempH][i] = entity;
        }
    }
}

