        int[] dx = new int[]{-1,0,1,0};
        int[] dy = new int[]{0,-1,0,1};
        for(int i = 0;i < 4;i++){
            int tx = x + dx[i];
            int ty = y + dy[i];
            if(tx >= 0 && tx < array.length && ty >= 0 && ty < array[0].length && array[tx][ty] == fruit)
                dfs(array,tx,ty,fruit);
        }
    }
