	static final int KAKI  = 2;
	static final int MIKAN = 3;

	int[][] field;
	int h, w, fruit;
	int[] dy = { 1, 0, -1,  0 };
	int[] dx = { 0, 1,  0, -1 };

	void run() {
		Scanner scan = new Scanner(System.in);
		while (true) {
			h = scan.nextInt();
			w = scan.nextInt();
