									}
									if (t.x-1>=0) {
										if (!check[t.x-1][t.y]&&field[t.x][t.y]==field[t.x-1][t.y]) queue[q++] = new Point(t.x-1,t.y);
									}
									if (t.y+1<W) {
										if (!check[t.x][t.y+1]&&field[t.x][t.y]==field[t.x][t.y+1]) queue[q++] = new Point(t.x,t.y+1);
									}
									if (t.y-1>=0) {
										if (!check[t.x][t.y-1]&&field[t.x][t.y]==field[t.x][t.y-1]) queue[q++] = new Point(t.x,t.y-1);
									}
								}
							}
							count++;
						}
					}
				}
