        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx < 0 || w <= nx || ny < 0 || h <= ny) {
                continue;
            }

            dfs(nx, ny, c);
        }
    }

