public class Main {
    private static char[][] chars;  // using to store inputs
    private static int row, col;
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        char symbol;
        while (true) {
            row = input.nextInt();
            col = input.nextInt();
            if (row == 0 && col == 0) {
                break;
            }
            chars = new char[row][col];
            for (int i = 0; i < row; i++) {
                chars[i] = input.next().toCharArray();
