import java.io.*;
import java.util.StringTokenizer;
import java.util.Arrays;

class Main {
	public static void main(String args[]) {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String buf;

		try {
			while (!(buf = br.readLine()).equals("0 0")) {
				StringTokenizer st = new StringTokenizer(buf);
				int H = Integer.parseInt(st.nextToken());
				int W = Integer.parseInt(st.nextToken());
				int field[][] = new int[H][W];
				int check[][] = new int[H][W];
				for (int i=0;i<H;i++) {
					Arrays.fill(check[i],0);
					buf = br.readLine();
					for (int j=0;j<W;j++) {
						if (buf.charAt(j)=='@') {
							field[i][j] = 0;
						} else if (buf.charAt(j)=='#') {
							field[i][j] = 1;
						} else {
							field[i][j] = 2;
						}
					}
				}
				int count = 1;
				for (int i=0;i<H;i++) {
					for (int j=0;j<W;j++) {
						if (check[i][j]==0) {
							count = search(field,check,H,W,i,j,count);
						}
					}
				}
				//printField(field,H,W);
				//printField(check,H,W);
				System.out.println(count-1);
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	public static int search(int[][] f,int[][] c,int H,int W,int x,int y,int count) {
		c[x][y] = count;
		if (x+1<H&&c[x+1][y]==0) {
			if (f[x][y]==f[x+1][y]) search(f,c,H,W,x+1,y,count);
		}
		if (x-1>=0&&c[x-1][y]==0) {
			if (f[x][y]==f[x-1][y]) search(f,c,H,W,x-1,y,count);
		}
		if (y+1<W&&c[x][y+1]==0) {
			if (f[x][y]==f[x][y+1]) search(f,c,H,W,x,y+1,count);
		}
		if (y-1>=0&&c[x][y-1]==0) {
			if (f[x][y]==f[x][y-1]) search(f,c,H,W,x,y-1,count);
		}
		return count+1;
	}

	public static void printField(int[][] a,int H,int W) {
		for (int i=0;i<H;i++) {
			for (int j=0;j<W;j++) System.out.print(a[i][j]);
			System.out.println();
		}
	}
}

import java.util.Scanner;

public class Main {
    private static char[][] chars;
    private static int row, col;
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        char symbol;
        while (true) {
            row = input.nextInt();
            col = input.nextInt();
            if (row == 0 && col == 0) {
                break;
            }
            chars = new char[row][col];
            for (int i = 0; i < row; i++) {
                chars[i] = input.next().toCharArray();
            }
            int n = 0;
            for (int i = 0; i < row; i++) {
                for (int j = 0; j < col; j++) {
                    symbol = chars[i][j];
                    if (symbol != '.') {
                        dfs(i, j, symbol);
                        n++;
                    }
                }
            }
            System.out.println(n);
        }
    }
    private static void dfs(int x, int y, char symbol) {
        chars[x][y] = '.';
        int dx, dy;
        int[] x_mov = {-1, 0, 0, 1}, y_mov = {0, -1, 1, 0};
        for (int i = 0; i < x_mov.length; i++) {
            dx = x + x_mov[i]; dy = y + y_mov[i];
            if (0 <= dx && dx < row && 0 <= dy && dy < col &&
                    chars[dx][dy] == symbol) {
                dfs(dx, dy, symbol);
            }
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.NoSuchElementException;
import java.util.Queue;

public class Main {
    int H,W;
    int[] dy = {1,-1,0,0};
    int[] dx = {0,0,1,-1};
    public void solve() {
        while(true){
            H = nextInt();
            W = nextInt();

            if(H + W == 0)break;
            char[][] ch = new char[H][];
            for(int i = 0;i < H;i++){
                ch[i] = next().toCharArray();
            }

            boolean[][] used = new boolean[H][W];
            int ans = 0;
            for(int i = 0;i < H;i++){
                for(int j = 0;j < W;j++){
                    if(used[i][j])continue;
                    ans++;
                    Queue<Integer> q = new ArrayDeque<Integer>();
                    q.add(i * 100 + j);
                    while(q.size() > 0){
                        int point = q.poll();
                        int y = point / 100;
                        int x = point % 100;
                        if(used[y][x])continue;
                        used[y][x] = true;

                        for(int k = 0;k < 4;k++){
                            int ny = dy[k] + y;
                            int nx = dx[k] + x;
                            if(ny < 0 || nx < 0 || ny >= H || nx >= W)continue;
                            if(ch[i][j] != ch[ny][nx])continue;
                            q.add(ny * 100 + nx);
                        }
                    }
                }
            }
            out.println(ans);
        }
    }

    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

    /* Input */
    private static final InputStream in = System.in;
    private static final PrintWriter out = new PrintWriter(System.out);
    private final byte[] buffer = new byte[2048];
    private int p = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (p < buflen)
            return true;
        p = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (buflen <= 0)
            return false;
        return true;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrint(buffer[p])) {
            p++;
        }
        return hasNextByte();
    }

    private boolean isPrint(int ch) {
        if (ch >= '!' && ch <= '~')
            return true;
        return false;
    }

    private int nextByte() {
        if (!hasNextByte())
            return -1;
        return buffer[p++];
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.Queue;
import java.util.LinkedList;
import java.util.NoSuchElementException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Seikichi KONDO (seikichi@kmc.gr.jp)
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AOJ0118 solver = new AOJ0118();
        solver.solve(1, in, out);
        out.close();
    }

    static final class AOJ0118 {
        @SuppressWarnings("unused")
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            while (true) {
                final int H = in.nextInt(), W = in.nextInt();
                if (H == 0 && W == 0) {
                    break;
                }

                final char[][] map = new char[H][];
                for (int i = 0; i < H; i++) {
                    map[i] = in.next().toCharArray();
                }

                // solve
                boolean visited[][] = new boolean[H][W];
                int result = 0;
                while (true) {
                    final Queue<Pair<Integer, Integer>> que = new LinkedList<Pair<Integer, Integer>>();

                    int sx, sy;
                    init:
                    {
                        for (int y = 0; y < H; y++) {
                            for (int x = 0; x < W; x++) {
                                if (!visited[y][x]) {
                                    sy = y;
                                    sx = x;
                                    break init;
                                }
                            }
                        }
                        break;
                    }
                    result++;
                    que.add(Pair.of(sy, sx));
                    visited[sy][sx] = true;
                    final int delta[][] = {{0, +1}, {+1, 0}, {0, -1}, {-1, 0}};
                    while (!que.isEmpty()) {
                        final Pair<Integer, Integer> p = que.remove();
                        for (int[] d : delta) {
                            final int ny = p.first() + d[0];
                            final int nx = p.second() + d[1];
                            if (ny < 0 || H <= ny || nx < 0 || W <= nx || visited[ny][nx] || map[ny][nx] != map[p.first()][p.second()]) {
                                continue;
                            }
                            visited[ny][nx] = true;
                            que.add(Pair.of(ny, nx));
                        }
                    }
                }

                out.println(result);
            }
        }

    }

    static final class Pair<F, S> {
        private final F first;
        private final S second;

        public static <F, S> Pair<F, S> of(F first, S second) {
            return new Pair<F, S>(first, second);
        }

        private Pair(F first, S second) {
            this.first = first;
            this.second = second;
        }

        public F first() {
            return this.first;
        }

        public S second() {
            return this.second;
        }

    }

    static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            if (!hasNext()) throw new NoSuchElementException();
            int n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

    }
}

import java.util.Scanner;
public class Main
{
	static int base[][];
	static int ans;
	static int H,W;
	public static void main(String arg[])
	{
		Scanner in=new Scanner(System.in);
		while(in.hasNext())
		{

			String str;
			H=in.nextInt();
			W=in.nextInt();
			if((H|W)==0)
				return;
			base=new int[H][W];
			for(int i=0;i<H;i++)
			{
				str=in.next();
				for(int j=0;j<W;j++)
				{
					if(str.charAt(j)=='@')
						base[i][j]=1;
					else if(str.charAt(j)=='#')
						base[i][j]=2;
					else if(str.charAt(j)=='*')
						base[i][j]=3;

				}
			}
			for(int i=0;i<H;i++)
			{
				for(int j=0;j<W;j++)
					System.out.print(base[i][j]);
				System.out.println();
			}
			ans=0;
			for(int i=0;i<H;i++)
				for(int j=0;j<W;j++)
				{
					if(base[i][j]==1)
					{
						solve1(i,j);
						ans++;
					}
					else if(base[i][j]==2)
					{
						solve2(i,j);
						ans++;
					}
					else if(base[i][j]==3)
					{
						solve3(i,j);
						ans++;
					}
				}
			for(int i=0;i<H;i++)
			{
				for(int j=0;j<W;j++)
					System.out.print(base[i][j]);
				System.out.println();
			}
			System.out.println(ans);
			System.out.println(H+" "+W);
		}
	}
	public static void solve1(int m, int n)
	{
		if(base[m][n]==1)
		{
			base[m][n]=0;
			if(m-1>=0&&base[m-1][n]==1)
				solve1(m-1,n);
			if(m+1<H&&base[m+1][n]==1)
				solve1(m+1,n);
			if(n-1>=0&&base[m][n-1]==1)
				solve1(m,n-1);
			if(n+1<W&&base[m][n+1]==1)
				solve1(m,n+1);
		}
	}
	public static void solve2(int m, int n)
	{
		if(base[m][n]==2)
		{
			base[m][n]=0;
			if(m-1>=0&&base[m-1][n]==2)
				solve2(m-1,n);
			if(m+1<H&&base[m+1][n]==2)
				solve2(m+1,n);
			if(n-1>=0&&base[m][n-1]==2)
				solve2(m,n-1);
			if(n+1<W&&base[m][n+1]==2)
				solve2(m,n+1);
		}
	}
	public static void solve3(int m, int n)
	{
		if(base[m][n]==3)
		{
			base[m][n]=0;
			if(m-1>=0&&base[m-1][n]==3)
				solve3(m-1,n);
			if(m+1<H&&base[m+1][n]==3)
				solve3(m+1,n);
			if(n-1>=0&&base[m][n-1]==3)
				solve3(m,n-1);
			if(n+1<W&&base[m][n+1]==3)
				solve3(m,n+1);
		}
	}
}

