public class Main {
	static FastReader in = new FastReader();
	static int[][] separate;
	static char[][] land;
	static int h;
	static int w;

	public static void main(String[] args) {
		while (run())
			;
	}

	private static boolean run() {
		h = in.nextInt();
		w = in.nextInt();
		if (h == 0 && w == 0)
			return false;
		land = in.nextCharArray2d(h, w);

		separate = new int[h][w];
		int owner = 0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (separate[i][j] > 0)
					continue;
				dfs(i, j, land[i][j], ++owner);
			}
		}
		System.out.println(owner);
		return true;
	}

	private static void dfs(int i, int j, char type, int owner) {
		if (land[i][j] != type || separate[i][j] > 0)
			return;
		separate[i][j] = owner;
		if (j > 0)
			dfs(i, j - 1, type, owner);
		if (i > 0)
			dfs(i - 1, j, type, owner);
		if (j < w - 1)
			dfs(i, j + 1, type, owner);
		if (i < h - 1)
			dfs(i + 1, j, type, owner);
	}

	static void printExit(Object msg) {
		System.out.println(msg);
		System.exit(0);
	}
}

class FastReader {
	private InputStream in = System.in;
	private byte[] buf = new byte[1024];
	private int charNum;
	private int charLen;
	private StringBuilder sb = new StringBuilder();

	public int read() {
		if (charLen == -1)
			throw new InputMismatchException();
		if (charNum >= charLen) {
			charNum = 0;
			try {
				charLen = in.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (charLen <= 0)
				return -1;
		}
		return buf[charNum++];
	}

	public String next() {
		int c = read();
		while (isWhitespace(c)) {
			c = read();
		}
		sb.setLength(0);
		do {
			sb.appendCodePoint(c);
			c = read();
		} while (!isWhitespace(c));
		return sb.toString();
	}

	public char[] nextCharArray() {
		return next().toCharArray();
	}

	public char[][] nextCharArray2d(int lines, int rows) {
		char[][] array = new char[lines][rows];
		for (int i = 0; i < lines; i++)
			array[i] = nextCharArray();
		return array;
	}

	public int nextInt() {
		return Integer.valueOf(next());
	}

	public boolean isWhitespace(int c) {
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}
}

import java.util.*;

public class Main {

	private static int H, W;   
	private static char[][] data;

	public static void main(String[] args) {

		Scanner fin = new Scanner(System.in);

		ArrayList<Integer> result = new ArrayList<Integer>();  
		data = new char[100][100];
		int x = 0,y = 0;
		H = fin.nextInt(); 
		W = fin.nextInt();			
		int count = 0;
		while(W != 0 && H != 0){			
			fin.nextLine();
			for(int i=0; i<H; i++ ){
				String line = fin.nextLine();  			
				for(int j=0; j<W; j++){
					data[i][j] = line.charAt(j);								
				}
			}
			for(int i=0; i<H; i++){
				for(int j=0; j<W; j++){
					if(data[i][j] == '@'||data[i][j] == '*'||data[i][j] == '#'){
						x = i ;
						y = j ;
						DFS(x,y);
						count++;
					}
				}
			}
			result.add(count);
			count = 0;
			W = fin.nextInt(); 
			H = fin.nextInt();
	    }

		for(int i=0; i < result.size(); i++){
			System.out.printf("%d\n",result.get(i));
		}

		fin.close();
	}

	private static int DFS(int x, int y){
		char c = data[x][y];
		data[x][y] = ' ';
		if(x >= 0 && x < H && y > 0 && y < W && data[x][y-1] == c){
			DFS(x, y-1);
		}
		if(x >= 0 && x < H && y >= 0 && y < W-1 && data[x][y+1] == c){
			DFS(x, y+1);
		}
		if(x > 0 && x < H && y >= 0 && y < W && data[x-1][y] == c){
			DFS(x-1, y);
		}
		if(x >= 0 && x < H-1 && y >= 0 && y < W && data[x+1][y] == c){
			DFS(x+1, y);
		}

		return 1;		
	}
}

