	public static void main(String[] args){
		Main app = new Main();
		Scanner sc = new Scanner(System.in);
		while(true){
			int count = 0;
			h = sc.nextInt();
			w = sc.nextInt();
			if(w == 0 || h == 0)break;
			map = new String[h][w];
			for(int i = 0; i < h; i++){
				char temp []= sc.next().toCharArray();
				for(int j = 0; j < w; j++){
					map[i][j] = String.valueOf(temp[j]);
				}
			}
			for(int i = 0; i < h; i++){
				for(int j = 0; j < w; j++){
					if(!map[i][j].equals("N")){
						app.solve(i,j,map[i][j]);
						count++;
					}
				}
			}
			System.out.println(count);
		}

	}
	void solve(int i, int j, String temp){
		if(map[i][j].equals(temp)){
			map[i][j] = "N";
			if(judge(i + 1,j)){
				solve(i + 1, j,temp);
			}
			if(judge(i - 1,j)){
				solve(i - 1, j,temp);
			}
			if(judge(i,j + 1)){
				solve(i, j + 1,temp);
			}
			if(judge(i,j - 1)){
				solve(i, j - 1,temp);
			}
		}
	}
	boolean judge(int x,int y){
		if(x < 0 || x >= h || y < 0 || y >= w)return false;
		else return true;
	}
}

import java.util.*;
public class Main {
	static Queue<Coordinate> q = new LinkedList<Coordinate>();
	static class Coordinate{
		int x,y;
		Coordinate(int x,int y){
			this.x = x;
			this.y = y;
		}
	}
	public static void main(String args[]){
		Scanner sc = new Scanner(System.in);
		while(true){
			int counter = 0;
			int N = sc.nextInt();
			int M = sc.nextInt();
			if(N==0&&M==0){
				break;
			}
			String input;
			char[][] test = new char[N+2][M+2];
			for(int i=0;i<(M+2);i++){
				test[0][i] = '.';
				test[N+1][i] = '.';
			}
			for(int i=0;i<(N+2);i++){
				test[i][0] = '.';
				test[i][M+1] = '.';
			}
			for(int i=1;i<N+1;i++){
				input = sc.next();
				for(int j=1;j<M+1;j++){
					test[i][j] = input.charAt(j-1);
				}
			}

			for(int i=1;i<N+1;i++){
				for(int j=1;j<M+1;j++){
					if(test[i][j]!='.'){
						Coordinate cor= new Coordinate(i,j);
						q.offer(cor);
						bfs(test,q);
						counter++;
					}
				}
			}
			System.out.println(counter);
		}
	}
	private static void bfs(char[][] test,Queue<Coordinate> q){
		Coordinate pair = q.poll();
		int x = pair.x, y = pair.y;
		char buf = test[x][y];
		test[x][y] = '.';
		if(buf!='.'){
			if(buf==test[x-1][y]){
				Coordinate cor = new Coordinate(x-1,y);
				q.add(cor);
			}
			if(buf==test[x+1][y]){
				Coordinate cor = new Coordinate(x+1,y);
				q.add(cor);
			}
			if(buf==test[x][y-1]){
				Coordinate cor = new Coordinate(x,y-1);
				q.add(cor);
			}
			if(buf==test[x][y+1]){
				Coordinate cor = new Coordinate(x,y+1);
				q.add(cor);
			}
		}
		if(!q.isEmpty()) {
			bfs(test,q);
		}
	}
}

