				}
			}
			for(int i = 0; i < h; i++){
				for(int j = 0; j < w; j++){
					if(!map[i][j].equals("N")){
						doing(map[i][j],i,j);
						count++;
					}
				}
			}
		}

		System.out.println(count);
	}
	static void doing(String temp, int i, int j){

		if(judge(i,j)){
			if(map[i][j].equals(temp)){
				map[i][j] = "N";
				if(judge(i + 1, j)){
					doing(temp,i + 1, j);
				}
				if(judge(i - 1, j)){
					doing(temp,i - 1, j);
				}

				if(judge(i, j + 1)){
					doing(temp,i, j + 1);
				}
				if(judge(i, j - 1)){
					doing(temp,i, j - 1 );
				}
			}


		}
	}
	static boolean judge(int x, int y){
		if(h <= x || x < 0 || y < 0 || y >= w ){
			return false;
