public class Main {

	Scanner sc = new Scanner(System.in);
	int[][] map;
	int X,Y;
	boolean[][] visited;

	void run(){
		while(true){
			X = sc.nextInt();
			Y = sc.nextInt();
			sc.nextLine();
			if((X|Y)==0) break;
			map = new int[Y][X];
			visited = new boolean[Y][X];
			for (int i = 0; i < Y; i++) {
				String temp = sc.nextLine();
				for (int j = 0; j < X; j++) {
					switch(temp.charAt(j)){
						case '@':
							map[i][j] = 0;
							break;
						case '#':
							map[i][j] = 1;
							break;
						case '*':
							map[i][j] = 2;
							break;
					}
				}
			}

			solve();

		}
	}

	void solve(){
		int ans = 0;
		for (int i = 0; i < Y; i++) {
			for (int j = 0; j < X; j++) {
				if(!visited[i][j]){
					ans++;
					bfs(i,j);
				}
			}
		}
		System.out.println(ans);

	}

	void bfs(int y,int x){
		LinkedList<P> que = new LinkedList<P>();
		que.offer(new P(x,y));
		visited[y][x] = true;
		int[] dx = {0,0,-1,1};
		int[] dy = {-1,1,0,0};
		while(!que.isEmpty()){
			P p = que.poll();
			for (int i = 0; i < 4; i++) {
