	public void loop(int y, int x, int d){
		if(x!=0 && map[y][x-1]==d && cost[y][x-1]==false){
			cost[y][x-1] = true;
			loop(y,x-1,d);
		}
		if(y!=0 && map[y-1][x]==d && cost[y-1][x]==false){
			cost[y-1][x] = true;
			loop(y-1,x,d);
		}
		if(x!=w-1 && map[y][x+1]==d && cost[y][x+1]==false){
			cost[y][x+1] = true;
			loop(y,x+1,d);
		}
		if(y!=h-1 && map[y+1][x]==d && cost[y+1][x]==false){
			cost[y+1][x] = true;
			loop(y+1,x,d);
		}
	}

