			int xx = x + st[k][1];
			int yy = y + st[k][0];

			if(!(0 <= xx && xx < W && 0 <= yy && yy < H)) {
				continue;
			}

			if(!State[yy][xx] && F[y][x].equals(F[yy][xx])) {
				State[yy][xx] = true;
				Fdiv(yy,xx);
			}
		}
	}
}

