public class Main {
	public static void main(String[] args) {
		Main p = new Main();
	}

	public Main(){
		Scanner sc = new Scanner(System.in);
		while(true){
			int h = sc.nextInt();
			int w = sc.nextInt();
			if(h==0 && w==0)
				break;

			char[][] field = new char[h+2][w+2];
			for(int i=1;i<=h;i++){
				String line = sc.next();
				for(int j=1;j<=w;j++){
					field[i][j] = line.charAt(j-1);
				}
			}
			for(int i=0;i<h+2;i++){
				field[0][i]=' ';
				field[h+1][i] = ' ';
				field[i][0] = ' ';
				field[i][w+1] = ' ';
			}

			solve(h, w, field);
		}
	}

	private void solve(int h, int w, char[][] field){
		int res = 0;
		for(int i=1;i<=h;i++){
			for(int j=1;j<=w;j++){
				if(field[i][j]!=' '){
					res++;
					rec(field, j, i);
				}
			}
		}

		System.out.println(res);
	}

	int[] dx = {-1, 0, 1, 0};
	int[] dy = {0, -1, 0, 1};
	private void rec(char[][] field, int x, int y){
		char cur = field[y][x];
		field[y][x]=' ';

		for(int i=0;i<4;i++){
			int nx = x+dx[i];
			int ny = y+dy[i];
			if(field[ny][nx]==cur){
				rec(field, nx, ny);
			}
		}
	}
}

