	final int MOD = 1000000007;
	int[] dx = { 1, 0, 0, -1 };
	int[] dy = { 0, 1, -1, 0 };

	char[][] f;
	boolean[][] visit;
	int H, W;

	void run() {
		for (;;) {
			H = sc.nextInt();
			W = sc.nextInt();
			if ((H | W) == 0) {
				return;
			}
			f = new char[H][W];
			visit = new boolean[H][W];
			for (int i = 0; i < H; i++) {
				String in = sc.next();
				for (int j = 0; j < W; j++) {
					f[i][j] = in.charAt(j);
				}
			}
			int cnt = 0;
			for (int i = 0; i < H; i++) {
				for (int j = 0; j < W; j++) {
					if (!visit[i][j]) {
						dfs(i, j, f[i][j]);
						cnt++;
					}
				}
			}
			System.out.println(cnt);
		}
	}

	void dfs(int h, int w, char ob) {
		visit[h][w] = true;
		for (int i = 0; i < 4; i++) {
			int nextH = h + dy[i];
			int nextW = w + dx[i];
			if (inner(nextH, nextW, H, W)) {
				if (!visit[nextH][nextW] && f[nextH][nextW] == ob) {
					dfs(nextH, nextW, ob);
				}
			}
		}
	}

