                return;
            int h = Integer.parseInt(nums[0]);
            int w = Integer.parseInt(nums[1]);
            char[][] maze = new char[h][w];
            for(int i = 0;i< h;i++)
            {
                String s = sc.nextLine();
                for(int j=0;j<w;j++)
                {
                    maze[i][j] = s.charAt(j);
                }
            }
            int res =0;
            for(int i=0;i<h;i++) {
                for (int j = 0; j < w; j++) {
                    if (maze[i][j] != '.')
                    {
                        solve(maze, i,j);
                        res++;
                    }
                }
            }
            System.out.println(res);
        }
    }
}

