import java.io.*;
import java.util.*;
import java.awt.Point;
public class Main{
	public static void main(String[] args) throws IOException, StackOverflowError{
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        List<Integer> Ansers = new ArrayList<Integer>();
        String line;

        while((line = in.readLine()) != null){
        	//first line
            String[] areaInformation = line.split(" ");
            int height = Integer.parseInt(areaInformation[0]);
            int width  = Integer.parseInt(areaInformation[1]);
            //separater
            if(height == 0 && width == 0){
                break;
            }

            //after second line
            byte[][] areaName       = new byte[height+1][width+1];
            boolean[][] someoneOwns = new boolean[height+1][width+1];
            //for each line i.e. current row
            for(int currentHeight = 0; currentHeight < height; ++currentHeight){
            	//get row data
                line = in.readLine();
                //outer zone
                areaName[currentHeight][width] = 0;
                someoneOwns[currentHeight][width] = true;
                for(int currentWidth = 0; currentWidth < width; ++currentWidth){
                	//get column data
                    String c = line.substring(currentWidth, currentWidth+1);
                    //outer zone
	                areaName[height][currentWidth] = 0;
    	            someoneOwns[height][currentWidth] = true;
	                //main area
                    if(c.equals("@")){
                        areaName[currentHeight][currentWidth] = 1;
                    }
                    else if(c.equals("#")){
                        areaName[currentHeight][currentWidth] = 2;
                    }
                    else if(c.equals("*")){
                        areaName[currentHeight][currentWidth] = 3;
                    }
                    someoneOwns[currentHeight][currentWidth] = false;
                }
            }

            int count = 0;
            for(int currentHeight = 0; currentHeight < height; ++currentHeight){
                for(int currentWidth = 0; currentWidth < width; ++currentWidth){
                    if(!someoneOwns[currentHeight][currentWidth]){
                        count++;
                        createOwnersArea(areaName, someoneOwns, currentHeight, currentWidth);
                    }
                }
            }

            Ansers.add(count);
        }

        for(Integer anser : Ansers){
            System.out.println(anser);
        }
    }
    public static void createOwnersArea(byte[][] areaName, boolean[][] someoneOwns, int currentHeight, int currentWidth){
    	Stack<Point> dfsArea = new Stack<Point>();
    	dfsArea.push(new Point(currentHeight, currentWidth));
    	someoneOwns[currentHeight][currentWidth] = true;
    	while(!dfsArea.empty()){
    		Point currentPosition = dfsArea.pop();
    		// System.out.println(currentPosition);
    		//check down
    		if(!someoneOwns[currentPosition.x+1][currentPosition.y]
    			&& areaName[currentPosition.x][currentPosition.y] == areaName[currentPosition.x+1][currentPosition.y]){
    			someoneOwns[currentPosition.x+1][currentPosition.y] = true;
    			dfsArea.push(new Point(currentPosition.x+1, currentPosition.y));
    		}
    		//check right
    		if(!someoneOwns[currentPosition.x][currentPosition.y+1]
    			&& areaName[currentPosition.x][currentPosition.y] == areaName[currentPosition.x][currentPosition.y+1]){
    			someoneOwns[currentPosition.x][currentPosition.y+1] = true;
    			dfsArea.push(new Point(currentPosition.x, currentPosition.y+1));
    		}
    		//check up
    		if(currentPosition.x > 0 && !someoneOwns[currentPosition.x-1][currentPosition.y]
    			&& areaName[currentPosition.x][currentPosition.y] == areaName[currentPosition.x-1][currentPosition.y]){
    			someoneOwns[currentPosition.x-1][currentPosition.y] = true;
    			dfsArea.push(new Point(currentPosition.x-1, currentPosition.y));
    		}
    		//check left
    		if(currentPosition.y > 0 && !someoneOwns[currentPosition.x][currentPosition.y-1]
    			&& areaName[currentPosition.x][currentPosition.y] == areaName[currentPosition.x][currentPosition.y-1]){
    			someoneOwns[currentPosition.x][currentPosition.y-1] = true;
    			dfsArea.push(new Point(currentPosition.x, currentPosition.y-1));
    		}
    	}
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.List;

public class Main {
	static FastReader in = new FastReader();
	static int[][] separate;
	static char[][] land;
	static int h;
	static int w;
	static List<Integer> ans = new ArrayList<Integer>();

	public static void main(String[] args) {
		try {
			while (run())
				;
		} catch (Exception e) {
		}
		for(int a : ans){
			System.out.println(a);
		}
	}

	private static boolean run() throws Exception {
		h = in.nextInt();
		w = in.nextInt();
		if (h == 0 && w == 0)
			return false;
		land = in.nextCharArray2d(h, w);

		separate = new int[h][w];
		int owner = 0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (separate[i][j] > 0)
					continue;
				dfs(i, j, land[i][j], ++owner);
			}
		}
		ans.add(owner);
		return true;
	}

	private static void dfs(int i, int j, char type, int owner) throws Exception {
		if (land[i][j] != type || separate[i][j] > 0)
			return;
		separate[i][j] = owner;
		if (j > 0)
			dfs(i, j - 1, type, owner);
		if (i > 0)
			dfs(i - 1, j, type, owner);
		if (j < w - 1)
			dfs(i, j + 1, type, owner);
		if (i < h - 1)
			dfs(i + 1, j, type, owner);
	}

	static void printExit(Object msg) {
		System.out.println(msg);
		System.exit(0);
	}
}

class FastReader {
	private InputStream in = System.in;
	private byte[] buf = new byte[1024];
	private int charNum;
	private int charLen;
	private StringBuilder sb = new StringBuilder();

	public int read() {
		if (charLen == -1)
			throw new InputMismatchException();
		if (charNum >= charLen) {
			charNum = 0;
			try {
				charLen = in.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (charLen <= 0)
				return -1;
		}
		return buf[charNum++];
	}

	public String next() {
		int c = read();
		while (isWhitespace(c)) {
			c = read();
		}
		sb.setLength(0);
		do {
			sb.appendCodePoint(c);
			c = read();
		} while (!isWhitespace(c));
		return sb.toString();
	}

	public char[] nextCharArray() {
		return next().toCharArray();
	}

	public char[][] nextCharArray2d(int lines, int rows) {
		char[][] array = new char[lines][rows];
		for (int i = 0; i < lines; i++)
			array[i] = nextCharArray();
		return array;
	}

	public int nextInt() {
		return Integer.valueOf(next());
	}

	public boolean isWhitespace(int c) {
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}
}

