            N = scan.nextByte();
            if(N ==0 && M ==0){break;}
            byte ans =0;
            //if(M==1&&N==0){System.out.println(ans);continue;}
            scan.nextLine();
            char [][] field =new char[M][N];
            for(byte i=0;i<M;i++){
             String line = scan.nextLine();
                for(byte j=0;j<N;j++){
                    field[i][j] = line.charAt(j);
                }
            }
            for(byte i=0;i<M;i++){
                for(byte j=0;j<N;j++){
                    if(field[i][j] != '.'){
                        ++ans;
                        dfs(i,j,field);

                    }
                }
            }
            System.out.println(ans);
    }
}
  public static void dfs(byte  y,byte x,char [][] field){
      char crop = field[y][x];
      field[y][x] = '.';
          if(0<=x+1&& x+1 < N &&0<=y&& y <M  && field[y][x+1]==crop)
              dfs((byte)y,(byte)(x+1),field);
          if(0<=x&& x < N &&0<=y+1&& y+1 <M  && field[y+1][x]==crop)
              dfs((byte)(y+1),(byte)x,field);
          if(0<=x-1&& x-1 < N &&0<=y&& y <M  && field[y][x-1]==crop)
              dfs((byte)y,(byte)(x-1),field);
          if(0<=x&& x < N &&0<=y-1&& y-1 <M  && field[y-1][x]==crop)
              dfs((byte)(y-1),(byte)x,field);
  }
}

import java.util.Scanner;

public class Main {
	static final int CHECK = 0;
	static final int RINGO = 1;
	static final int KAKI  = 2;
	static final int MIKAN = 3;

	int[][] field;
	int h, w;
	void run() {
		Scanner scan = new Scanner(System.in);
		while (true) {
			h = scan.nextInt();
			w = scan.nextInt();
			if (h + w == 0)
				break;
			field = new int[h][];
			for (int i = 0; i < h; i++) {
				field[i] = new int[w];
				char[] fruit = scan.next().toCharArray();
				for (int j = 0; j < w; j++) {
					if (fruit[j] == '@')
						field[i][j] = RINGO;
					else if (fruit[j] == '#')
						field[i][j] = KAKI;
					else
						field[i][j] = MIKAN;
				}
			}
			int ans = 0;
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					if (field[i][j] != CHECK) {
						ans++;
						bfs(i, j, field[i][j]);
					}
				}
			}
			System.out.println(ans);
		}
	}

	void bfs(int y, int x, int f) {
		field[y][x] = CHECK;
		int[] dy = { 1, 0, -1,  0 };
		int[] dx = { 0, 1,  0, -1 };
		for (int i = 0; i < 4; i++) {
			int ny = y + dy[i];
			int nx = x + dx[i];
			if (ny < 0 || nx < 0 || ny >= h || nx >= w)
				continue;
			if (field[ny][nx] != f)
				continue;
			bfs(y + dy[i], x + dx[i], f);
		}
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

import java.util.*;

public class Main {

	private static int H, W;   
	private static char[][] data;

	public static void main(String[] args) {

		Scanner fin = new Scanner(System.in);

		ArrayList result = new ArrayList();  
		data = new char[100][100];
		int x = 0,y = 0;
		H = fin.nextInt(); 
		W = fin.nextInt();			
		int count = 0;
		while(W != 0 && H != 0){			
			fin.nextLine();
			for(int i=0; i<H; i++ ){
				String line = fin.nextLine().toString().replace(" ", "");  			
				for(int j=0; j<W; j++){
					data[i][j] = line.charAt(j);								
				}
			}
			for(int i=0; i<H; i++){
				for(int j=0; j<W; j++){
					if(data[i][j] == '@'||data[i][j] == '*'||data[i][j] == '#'){
						x = i ;
						y = j ;
						DFS(x,y);
						count++;
					}
				}
			}
			result.add(count);
			count = 0;
			W = fin.nextInt(); 
			H = fin.nextInt();
	    }

		for(int i=0; i < result.size(); i++){
			System.out.printf("%d\n",result.get(i));
		}
	}

	private static int DFS(int x, int y){
		char c = data[x][y];
		data[x][y] = ' ';
		if(x >= 0 && x < H && y > 0 && y < W && data[x][y-1] == c){
			DFS(x, y-1);
		}
		if(x >= 0 && x < H && y >= 0 && y < W-1 && data[x][y+1] == c){
			DFS(x, y+1);
		}
		if(x > 0 && x < H && y >= 0 && y < W && data[x-1][y] == c){
			DFS(x-1, y);
		}
		if(x >= 0 && x < H-1 && y >= 0 && y < W && data[x+1][y] == c){
			DFS(x+1, y);
		}

		return 1;		
	}
}

