public class Main{
	static int X,Y;
	static int[][] field;
	static boolean[][] done;
	static final int[] dx = {1,0,-1,0};
	static final int[] dy = {0,1,0,-1};
	static int ans;

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);

		while(true){
			Y = sc.nextInt();
			X = sc.nextInt();
			if(X==0 & Y==0) break;

			field = new int[X][Y];
			done = new boolean[X][Y];
			for(int y = 0; y < Y; y++){
				char []input = sc.next().toCharArray();
				for(int x = 0; x < X; x++){
					done[x][y] = false;					
					if(input[x] == '#'){
						field[x][y] = 0;
					}else if(input[x] == '@'){
						field[x][y] = 1;
					}else if(input[x] == '*'){
						field[x][y] = 2;
					}
				}
			}
			ans = 0;
			for(int y = 0; y < Y; y++){
				for(int x = 0; x < X; x++){
					if(!done[x][y]){
						ans++;
//						dfs(x,y,field[x][y]);
						bfs(x,y,field[x][y]);
					}					
				}
			}
			System.out.println(ans);
		}
	}

	private static void bfs(int x, int y, int type) {
		LinkedList<xy> ll = new LinkedList<xy>();
		ll.add(new xy(x,y));
		while(!ll.isEmpty()){
			xy p = ll.poll();
			for(int i = 0; i < 4; i++){
				if(p.x+dx[i]<0 | p.x+dx[i]>=X) continue;
				if(p.y+dy[i]<0 | p.y+dy[i]>=Y) continue;
				if(done[p.x+dx[i]][p.y+dy[i]]) continue;
				if(field[p.x+dx[i]][p.y+dy[i]] != type) continue;
				done[p.x+dx[i]][p.y+dy[i]] = true;
				ll.add(new xy(p.x+dx[i], p.y+dy[i]));
			}
		}
	}

