import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class Main{
	static Queue<Pair> queue = new LinkedList<Pair>();

	static class Pair {
		int x, y;

		Pair(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}

	public static void main(String args[]) {
		Scanner sc = new Scanner(System.in);
		int width, height;
		int area[][];
		int tree[][];

		while (true) {
			height = sc.nextInt();
			width = sc.nextInt();
			if ((height | width) == 0) {
				break;
			}
			tree = new int[height][width];
			area = new int[height][width];
			for (int i = 0; i < height; i++) {
				String s = sc.next();
				for (int j = 0; j < width; j++) {
					tree[i][j] = s.charAt(j);
					area[i][j] = 0;
				}
			}
			System.out.println(f(tree, area, height, width));
		}
	}

	public static int f(int tree[][], int area[][], int h, int w) {
		int count = 0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (area[i][j] == 0) {
					count++;
					g(tree, area, i, j, h, w, count);
					h(tree, area, i, j, h, w, count);
				}
			}
		}
		return count;
	}

	public static void g(int tree[][], int area[][], int i, int j, int h, int w, int count) {
		if (area[i][j] != 0) {
			return ;
		}
		int x = tree[i][j];
		area[i][j] = count;
		if (0 <= i - 1 && tree[i - 1][j] == x) {
			Pair p = new Pair(i - 1, j);
			queue.add(p);
		}
		if (i + 1 < h && tree[i + 1][j] == x) {
			Pair p = new Pair(i + 1, j);
			queue.add(p);
		}
		if (0 <= j - 1 && tree[i][j - 1] == x) {
			Pair p = new Pair(i, j - 1);
			queue.add(p);
		}
		if (j + 1 < w && tree[i][j + 1] == x) {
			Pair p = new Pair(i, j + 1);
			queue.add(p);
		}
	}

	public static void h(int tree[][], int area[][], int i, int j, int h, int w, int count) {
		while (!queue.isEmpty()) {
			Pair p = queue.poll();
			g(tree, area, p.x, p.y, h, w, count);
		}
	}
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		while (true) {
			int a = scanner.nextInt();
			int b = scanner.nextInt();
			if (a == 0 && b == 0)
				break;
			char[][] map = new char[a][b];
			for (int i = 0; i < a; i++) {
				map[i] = scanner.next().toCharArray();
			}
			int count = 0;
			for (int i = 0; i < a; i++) {
				for (int j = 0; j < b; j++) {
					if (map[i][j] != '-') {
						count++;
						solve(map[i][j], map, i, j);
					}
				}
			}
			System.out.println(count);
		}
	}

	private static void solve(char c, char[][] map, int y, int x) {
		int[] a = { -1, 0, 0, 1 };
		int[] b = { 0, -1, 1, 0 };
		Deque<int[]> deque = new ArrayDeque<int[]>();
		deque.push(new int[] { y, x });
		while (!deque.isEmpty()) {
			int[] p = deque.pop();
			int yp = p[0];
			int xp = p[1];
			map[yp][xp] = '-';
			for (int i = 0; i < a.length; i++) {
				int yn = yp + a[i];
				int xn = xp + b[i];
				if (yn >= 0 && map.length > yn && xn >= 0 && map[0].length > xn
						&& map[yn][xn] == c) {
					boolean flag = true;
					for (int[] t : deque) {
						if (t[0] == yn && t[1] == xn) {
							flag = false;
							break;
						}
					}
					if (flag) {
						deque.push(new int[] { yn, xn });
					}
				}
			}
		}
	}

}

