				}
			}
			for(int i=0; i<H; i++){
				for(int j=0; j<W; j++){
					if(data[i][j] == '@'||data[i][j] == '*'||data[i][j] == '#'){
						x = i ;
						y = j ;
						DFS(x,y);
						count++;
					}
				}
			}
			result.add(count);
			count = 0;
			W = fin.nextInt(); 
