			}
			for (int y = 0; y < h; y++) {
				for (int x = 0; x < w; x++) {
					if (map[y][x] != 'x') {
						solve(y, x, map[y][x]);
						section++;
					}
				}
			}
			System.out.println(section);
		}
	}

	void solve(int y, int x, char c) {
		if (y < 0 || x < 0 || y >= h || x >= w || map[y][x] != c) return;
		map[y][x] = 'x';
		solve(y + 1, x, c);
		solve(y - 1, x, c);
		solve(y, x + 1, c);
		solve(y, x - 1, c);
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

