public class Main{
	public static void main(String[] args)throws Exception{
		new Main().solve();
		//		new Q0118().make_sample();
	}
	void solve(){
		Scanner sc=new Scanner(System.in);
		while(true){
			int h=sc.nextInt();
			int w=sc.nextInt();
			if(h==0&&w==0)break;
			char[][] table=new char[h][w];
			checked=new boolean[h][w];
			for(int i=0;i<h;i++){
				table[i]=sc.next().toCharArray();
				//#,*,@
			}
			int count=0;
			for(int i=0;i<h;i++){
				for(int j=0;j<w;j++){
					if(!checked[i][j]){
						dfs(table,j,i,w,h);
						count++;
					}
				}
			}
			System.out.println(count);
		}
	}
	int[] dx={1,-1,0,0};
	int[] dy={0,0,-1,1};
	boolean[][] checked;
	void dfs(char[][] table,int x,int y,int w,int h){
		ArrayDeque<State>dq=new ArrayDeque<State>(w*h);
		dq.addFirst(new State(x,y));
		while(!dq.isEmpty()){
			State s=dq.pollFirst();
			for(int i=0;i<4;i++){
				int nextx=s.x+dx[i];
				int nexty=s.y+dy[i];
				if(nextx<0||nextx>w-1||nexty<0||nexty>h-1)continue;
				if(table[s.y][s.x]==table[nexty][nextx]&&!checked[nexty][nextx]){
					checked[nexty][nextx]=true;
					dq.addFirst(new State(nextx,nexty));
				}
			}
		}
	}
	class State{
		int x;
		int y;
		State(int x,int y){
			this.x=x;
			this.y=y;
		}
	}
	void make_sample(){
		System.out.println("100 100");
		for(int i=0;i<100;i++){
			for(int j=0;j<100;j++){
				int a=(int)(Math.random()*3);
				switch(a){
				case 0:
					System.out.print("@");
					break;
				case 1:
					System.out.print("*");
					break;
				case 2:
					System.out.print("#");
				}
			}
			System.out.println();
		}
	}
}

