	public Main() throws IOException{
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		List<Integer> Ans = new ArrayList<Integer>();
		String line;

		while((line = in.readLine()) != null){
			String[] dst = line.split(" ");
			int h = Integer.parseInt(dst[0]);
			int w = Integer.parseInt(dst[1]);

			if(h==0 && w==0){
				break;
			}

			String[][] data = new String[h+1][w+1];
			for(int j=1; j<=h; j++){
				line = in.readLine();
				for(int i=1; i<=w; i++){
					data[j][i] = line.substring(i-1, i);
				}
			}

			for(int j=0; j<=h; j++){
				data[j][0] = " ";
			}

			for(int i=0; i<=w; i++){
				data[0][i] = " ";
			}

			int count = 0;
			String prev = "";
			for(int j=1; j<=h; j++){
				for(int i=1; i<=w; i++){
					if(!data[j][i].equals(prev)){
						prev = "";
					}

					if(!data[j][i].equals(data[j-1][i]) && !data[j][i].equals(data[j][i-1])){
						count++;
					}

					else if(data[j][i].equals(data[j-1][i]) && data[j][i].equals(data[j][i-1]) && !data[j][i].equals(data[j-1][i-1])){
						if(prev.equals("")){
							count--;
						}
					}

					else if(data[j][i].equals(data[j-1][i])){
						prev = data[j][i];
					}
				}
			}

			Ans.add(count);
		}

		for(int n=0; n<Ans.size(); n++){
			System.out.println(Ans.get(n));
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.NoSuchElementException;
import java.util.Queue;

public class Main {
	int H,W;
	int[] dy = {1,-1,0,0};
	int[] dx = {0,0,1,-1};
	public void solve() {
		while(true){
			H = nextInt();
			W = nextInt();

			if(H + W == 0)break;
			char[][] ch = new char[H][];
			for(int i = 0;i < H;i++){
				ch[i] = next().toCharArray();
			}

			boolean[][] used = new boolean[H][W];
			int ans = 0;
			for(int i = 0;i < H;i++){
				for(int j = 0;j < W;j++){
					if(used[i][j])continue;
					ans++;
					Queue<Integer> q = new ArrayDeque<Integer>();
					q.add(i * 100 + j);
					while(q.size() > 0){
						int point = q.poll();
						int y = point / 100;
						int x = point % 100;
						if(used[y][x])continue;
						used[y][x] = true;

						for(int k = 0;k < 4;k++){
							int ny = dy[k] + y;
							int nx = dx[k] + x;
							if(ny < 0 || nx < 0 || ny >= H || nx >= W)continue;
							if(ch[i][j] != ch[ny][nx])continue;
							q.add(ny * 100 + nx);
						}
					}
				}
			}
			out.println(ans);
		}
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.io.*;
public class Main{
    public static void main(String args[]){
		Main a = new Main();
		a.run();
    }

    String[][] map;
    int H = -1;
	int W = -1;

    public void run(){
        try{
            BufferedReader stdReader = new BufferedReader(new InputStreamReader(System.in));
            String line = "";
            int tempH = 0;

            while(!(line = stdReader.readLine()).equals("0 0")){
                if(W==-1){
                    H = Integer.valueOf(line.split(" ")[0]);
                    W = Integer.valueOf(line.split(" ")[1]);
                    map = new String[H][W];
                }else if(!line.equals("0 0")){
                    setLine(tempH, line);
                    tempH += 1;
                }				
				if(tempH == H){
					solve();
					W = -1;
					H = -1;
					tempH = 0;
				}
            }
            stdReader.close();
        }catch(Exception e){
			e.getStackTrace();
        }
    }

    private void solve(){
        int person = 0;
        int[] point;
		for(int i = 0; i < H; i++){
			for(int j = 0; j < W; j++){
				if(!map[i][j].equals("_")){
					int[] in = {i,j};
					search(in);
					person++;
				}
			}
		}
        System.out.println(person);
    }

    private void search(int[] point){
        int x = point[0];
        int y = point[1];
        String temp = map[x][y];
		map[x][y] = "_";

		if(x+1<H){
			if(map[x+1][y].equals(temp)&&!map[x+1][y].equals("_")){
				int[] neoPoint = {x+1, y};
				search(neoPoint);
			}
		}
		if(y+1<W){
			if(map[x][y+1].equals(temp)&&!map[x][y+1].equals("_")){
				int[] neoPoint = {x, y+1};
				search(neoPoint);
			}
		}
		if(x-1>=0){
			if(map[x-1][y].equals(temp)&&!map[x-1][y].equals("_")){
				int[] neoPoint = {x-1, y};
				search(neoPoint);
			}
		}
		if(y-1>=0){
			if(map[x][y-1].equals(temp)&&!map[x][y-1].equals("_")){
				int[] neoPoint = {x, y-1};
				search(neoPoint);
			}
		}
    }

    private void setLine(int tempH, String input){
        for(int i = 0; i < map[tempH].length; i++){
            String entity = input.substring(i,i+1);
            map[tempH][i] = entity;
        }
    }
}

import java.util.*;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		while(true){
			int h = sc.nextInt();
			int w = sc.nextInt();
			if(h==0 && w==0) break;

			char[][] map = new char[h][w];
			for(int i=0;i<h;i++) map[i] = sc.next().toCharArray();

			ArrayDeque<Integer> p = new ArrayDeque<Integer>();
			ArrayDeque<Integer> q = new ArrayDeque<Integer>();
			int count = 0;
			char c = '.';
			int x, y;

			for(int i=0;i<h;i++){
				for(int j=0;j<w;j++){
					if(map[i][j]!='.'){
						count++;
						c = map[i][j];
						p.offer(j);
						q.offer(i);
						while(p.size()!=0){
							x = p.poll();
							y = q.poll();
							map[y][x] = '.';

							if(x!=0 && map[y][x-1]==c){
								p.offer(x-1);
								q.offer(y);
							}
							if(x!=w-1 && map[y][x+1]==c){
								p.offer(x+1);
								q.offer(y);
							}
							if(y!=0 && map[y-1][x]==c){
								p.offer(x);
								q.offer(y-1);
							}
							if(y!=h-1 && map[y+1][x]==c){
								p.offer(x);
								q.offer(y+1);
							}
						}
					}
				}
			}
			System.out.println(count);
		}
	}	
}

