  public static void dfs(int x,int y,char [][] field){
      char crop = field[y][x];
      field[y][x] = '.';
      char [] dx= {1,0,-1,0};

      for(int i=0;i<3;i++){
          int nx = x+dx;
          int ny = x + dx^1;
          if(0<=nx 
            && nx < N 
            &&0<=ny 
            &&ny <M 
            && field[ny][nx].equals(crop)){
              dfs(ny,nx,field);
          }
      }
  }
