public class Main
  static Scanner sc = new Scanner(System.in);
  static char [][] map;
  static char tmp_fruit;
  static int [] dx = {0, -1, 0, 1}, dy = {1, 0, -1, 0};
  static int H;
  static int W;
  static int ans;

  public static void main(String [] args){
