public class Main {
    private static char[][] room;
    private static boolean[][] roomVisited;
    private static int count;
    private static int[][] directions = {{1,0}, {0,1}, {0,-1}, {-1,0}};


    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int w, h;
        String lineOfInput;

        while(true) {
            lineOfInput = sc.nextLine();
            w = Integer.parseInt(lineOfInput.split(" ")[0]);
            h = Integer.parseInt(lineOfInput.split(" ")[1]);


            if (w == 0 && h == 0) break;

            room = new char[h][w];
            roomVisited = new boolean[h][w];
            for (boolean[] row: roomVisited)
                Arrays.fill(row, false);
            count = 0;

//            sc.nextLine(); // for empty line
            for (int i = 0; i < h; i++) {
                lineOfInput = sc.nextLine();
                for (int j = 0; j < w; j++) {
                    room[i][j] = lineOfInput.charAt(j);
                }
            }

            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    if (!roomVisited[y][x]) {
                        roomVisited[y][x] = true;
                        dfs(x, y);
                        count++;
                    }
                }
            }

            System.out.println(count);
        }
    }

    private static void dfs(int x, int y) {
        int nx, ny;
        for (int[] direction: directions) {
