public class Main{
	static FastReader in = new FastReader();
	static int[][] separate;
	static char[][] land;
	static int h;
	static int w;

	public static void main(String[] args) {
		h = in.nextInt();
		w = in.nextInt();
		land = in.nextCharArray2d(h, w);
		int zero = in.nextInt();
		zero = in.nextInt();

		separate = new int[h][w];
		int owner = 0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (separate[i][j] > 0) continue;
				dfs(i, j, land[i][j], ++owner);
			}
		}
		printExit(owner);
	}

	private static void dfs(int i, int j, char type, int owner) {
		if (land[i][j] != type || separate[i][j] > 0) return;
		separate[i][j] = owner;
		if (j > 0) dfs(i, j - 1, type, owner);
		if (i > 0) dfs(i - 1, j, type, owner);
		if (j < w - 1) dfs(i, j + 1, type, owner);
		if (i < h - 1) dfs(i + 1, j, type, owner);
	}

	static void printExit(Object msg) {
		System.out.println(msg);
		System.exit(0);
	}
}

class FastReader{
	private InputStream in = System.in;
	private byte[] buf = new byte[1024];
	private int charNum;
	private int charLen;
	private StringBuilder sb = new StringBuilder();

	public int read() {
		if (charLen == -1) throw new InputMismatchException();
		if (charNum >= charLen) {
			charNum = 0;
			try {
				charLen = in.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (charLen <= 0) return -1;
		}
		return buf[charNum++];
	}

	public String next() {
		int c = read();
		while (isWhitespace(c)) {
			c = read();
		}
		sb.setLength(0);
		do {
			sb.appendCodePoint(c);
			c = read();
		} while (!isWhitespace(c));
		return sb.toString();
	}

	public char[] nextCharArray() {
		return next().toCharArray();
	}

	public char[][] nextCharArray2d(int lines, int rows) {
		char[][] array = new char[lines][rows];
		for (int i = 0; i < lines; i++)
			array[i] = nextCharArray();
		return array;
	}

	public boolean isWhitespace(int c) {
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}
}

