			}

			if(j > 0 && field[i][j-1] == c){
				field[i][j-1] = '.';
				si.push(i); sj.push(j-1);
			}

			if(j < w-1 && field[i][j+1] == c){
				field[i][j+1] = '.';
				si.push(i); sj.push(j+1);
			}
		}
