				ans++;
				LinkedList<Point> open=new LinkedList<Point>();
				open.add(new Point(r[0],r[1]));
				char mark=c[r[0]][r[1]];
				while(!open.isEmpty()){
					Point now=open.poll();
					c[now.x][now.y]='&';
					for(int i=0; i<4; i++){
						if(now.x+vx[i]<0 || now.x+vx[i]>=X || now.y+vy[i]<0 || now.y+vy[i]>=Y)	continue;
						if(c[now.x+vx[i]][now.y+vy[i]]==mark){
