			}
			out.println(ans);
		}
	}
	int[] isFin(char[][] c,int X,int Y){
		int[] ans={-1,-1};
		for(int y=0; y<Y; y++){
			for(int x=0; x<X; x++){
				//out.print(c[x][y]);
				if(c[x][y]!='&'){
					ans[0]=x;	ans[1]=y;
					return ans;
				}
			}
			//out.println();
		}
		//out.println();
		return ans;
	}

	// Red and Black 横型探索
	void AOJ1130(){
		while(sc.hasNext()){
			int X=sc.nextInt(), Y=sc.nextInt(),sx=0,sy=0,ans=0;
			if(X==0)	break;
			char[][] c=new char[X][Y];
