				for(int x = 0; x < X; x++){
					done[x][y] = false;					
					if(input[x] == '#'){
						field[x][y] = 0;
					}else if(input[x] == '@'){
						field[x][y] = 1;
					}else if(input[x] == '*'){
						field[x][y] = 2;
					}
				}
			}
