		for(int i=0;i<h;i++){
			for(int j=0;j<w;j++){
				if(v[i][j]==0){
					ans++;
					char aim = map[i][j];
					node t = new node (i,j);
					if(Q.size()!=0)  {Q.clear();}
					Q.offer(t);
					while(Q.size()!=0){
						node tem = Q.poll();
						int x = tem.x;
						int y = tem.y;
						for(int k=0;k<4;k++){
							int xx = x+dx[k];
							int yy = y+dy[k];
							if(xx>=0&&xx<h&&yy>=0&&yy<w&&map[xx][yy]==aim&&v[xx][yy]==0){
								v[xx][yy]=1;
								node temp = new node (xx,yy);
								Q.offer(temp);
							}
						}
					}

				}

			}
		}


		System.out.println(ans);
		return ;

	}
}

