			arr[i+1][j] = '1';
			a_search(i+1, j, tmp);
		}

		if(j-1 >= 0 && arr[i][j-1] == tmp) {
			arr[i][j-1] = '1';
			a_search(i, j-1, tmp);
		}

		if(j+1 < w && arr[i][j+1] == tmp) {
			arr[i][j+1] = '1';
			a_search(i, j+1, tmp);
		}
	}


