	void check(int h, int w, char ob) {
		visit[h][w] = true;
		LinkedList<Grid> que = new LinkedList<Grid>();
		que.add(new Grid(h, w));
		while (!que.isEmpty()) {
			Grid now = que.poll();
			for (int i = 0; i < 4; i++) {
				int nextH = now.h + dy[i];
				int nextW = now.w + dx[i];
				if (inner(nextH, nextW, H, W)) {
