			int x = 0;
			for(int i=0;i<h;i++){
				for(int j=0;j<w;j++){
					if(m[i][j]!='.'){
						x++;
						List<int[]> l = new ArrayList<int[]>();
						char c = m[i][j];
						m[i][j] = '.';
						l.add(new int[]{i,j});
						while(!l.isEmpty()){
							List<int[]> next = new ArrayList<int[]>();
							for(int[] a:l){
								int u = a[0];
								int v = a[1];
