public class Main {
    private static char[][] farm = new char[100][100];
    private static char[][] visited = new char[100][100];
    private static int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
    private static Queue<P> queue = new LinkedList<P>();
    private static int result = 0;
    private static int H, W;
    static class P{
        int y, x;
        P(int y, int x){
            this.x=x;
            this.y=y;
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner input = new Scanner(System.in);
        H = input.nextInt();W = input.nextInt();
        while (H != 0){
            for (int y = 0; y < H; y++) {
                char[] line = input.next().toCharArray();
                farm[y] = line;
                for (int x = 0; x < W; x++) {
                    visited[y][x] = 'O';
                }
            }
            for (int y = 0; y < H; y++) {
                for (int x = 0; x < W; x++) {
                    if(visited[y][x]=='O'){
                        bfs(y, x);
                        result += 1;
                    }
                }
            }
            System.out.println(result);
            result = 0;
            H = input.nextInt();W = input.nextInt();
        }
    }

    public static void bfs(int iy, int ix){
        visited[iy][ix] = 'X';
        queue.add(new P(iy,ix));
        for (;!queue.isEmpty();){
            P p = queue.poll();
            int y = p.y, x = p.x;
            for (int i = 0; i < 4; i++) {
                int ny = y + dy[i], nx = x + dx[i];
                if(0<=ny && ny<H && 0<=nx && nx<W && visited[ny][nx]=='O' && farm[ny][nx]==farm[y][x]){
                    visited[ny][nx] = 'X';
                    queue.add(new P(ny, nx));
                }
            }
        }
    }
}

import java.util.*;

public class Main {
    private static char[][] room;
    private static boolean[][] roomVisited;
    private static int count;
    private static int[][] directions = {{1,0}, {0,1}, {0,-1}, {-1,0}};


    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int w, h;
        String lineOfInput;

        while(true) {
            w = sc.nextInt();
            h = sc.nextInt();

            if (w == 0 && h == 0) break;

            room = new char[h][w];
            roomVisited = new boolean[h][w];
            for (boolean[] row: roomVisited)
                Arrays.fill(row, false);
            count = 0;

            sc.nextLine(); // for empty line
            for (int i = 0; i < h; i++) {
                lineOfInput = sc.nextLine();
                for (int j = 0; j < w; j++) {
                    room[i][j] = lineOfInput.charAt(j);
                }
            }

            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    if (!roomVisited[y][x]) {
                        roomVisited[y][x] = true;
                        dfs(x, y);
                        count++;
                    }
                }
            }

            System.out.println(count);
        }
    }

    private static void dfs(int x, int y) {
        int nx, ny;
        for (int[] direction: directions) {
            nx = x + direction[0];
            ny = y + direction[1];
            if (nx >= 0 && ny >= 0 && nx < room[0].length && ny < room.length) {
                if (!roomVisited[ny][nx] && room[y][x] == room[ny][nx]) {
                    roomVisited[ny][nx] = true;
                    dfs(nx, ny);
                }
            }
        }
    }
}

