	void label(char map[][],int i,int j,char x){

		int dx[] ={0,0,-1,1};

		int dy[] ={1,-1,0,0};

		for(int a = 0 ; a < 4;a++){

			int ni = i + dx[a];

			int nj = j + dy[a];

			if(map[ni][nj] == x){

				map[ni][nj] = '_';

				label(map,ni,nj,x);

			}

		}

	}



