        for(int i = 0; i < h; i++) {
            grid[i] = sc.next().toCharArray();
        }
        return true;
    }

    public static void dfs(int i, int j , char c) {
        // stopping condition
        if(i < 0 || i >= h || j < 0 || j >= w) return;
        if(grid[i][j] != c) return;

        // marking where already visit
        grid[i][j] = '.';

        // recursion
        for(int k = 0; k < 4; k++) dfs(i + dx[k], j + dy[k], c);
    }

    public static void solve() {
        int ans = 0;

        // dfs
        for(int i = 0; i < h; i++) {
            for(int j = 0; j < w; j++) {
                if(grid[i][j] != '.') {
                    ans++;
                    dfs(i, j, grid[i][j]);
                }

            }
        }

        System.out.println(ans);
    }

    public static void main(String[] args) {
        while(read()) solve();
    }

}

import java.util.Scanner;

public class Main {
	char[][] map;
	int h = 0;
	int w = 0;

	void run() {
		Scanner scan = new Scanner(System.in);
		while (true) {
			h = scan.nextInt();
			w = scan.nextInt();
			if (w == 0 && h == 0) break;
			map = new char[h][];
			int section = 0;
			scan.nextLine();
			for (int i = 0; i < h; i++)
				map[i] = new char[w];
			for (int y = 0; y < h; y++) {
				String str = scan.nextLine();
				for (int x = 0; x < w; x++) {
					map[y][x] = str.charAt(x);
				}
			}
			for (int y = 0; y < h; y++) {
				for (int x = 0; x < w; x++) {
					if (map[y][x] != 'x') {
						solve(y, x, map[y][x]);
						section++;
					}
				}
			}
			System.out.println(section);
		}
	}

	void solve(int y, int x, char c) {
		if (y < 0 || x < 0 || y >= h || x >= w || map[y][x] != c) return;
		map[y][x] = 'x';
		solve(y + 1, x, c);
		solve(y - 1, x, c);
		solve(y, x + 1, c);
		solve(y, x - 1, c);
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

