	private static char[][] dfs(int x,int y,char[][] test){
		char buf = test[x][y];
		test[x][y] ='.';
		if(buf!='.'){
			if(buf==test[x-1][y]){
				test = dfs(x-1,y,test);
			}
			if(buf==test[x+1][y]){
				test = dfs(x+1,y,test);
			}
			if(buf==test[x][y-1]){
				test = dfs(x,y-1,test);
			}
			if(buf==test[x][y+1]){
				test = dfs(x,y+1,test);
			}
		}
		return test;
	}
