            for(int i = 0;i < H;i++){
                array[i] = input.next().toCharArray();
            }
            for(int i = 0;i < H;i++){
                for(int j = 0;j < W;j++){
                    char fruit = array[i][j];
                    if(fruit == '@' || fruit == '#' || fruit == '*'){
                        result++;
                        dfs(array,i,j,fruit);
                    }
                }
            }
            System.out.println(result);
            result = 0;
        }
