			for(int i=0;i<row;i++){
				bf.append(scanner.nextLine().trim());
			}
			bf.trimToSize();

			char c;
			int result=0;
			List<Integer> list=new ArrayList<Integer>();
			for(int j=0;j<bf.length();j++){
				if(list.contains(j)){
					continue;
				}
				c=bf.charAt(j);
				list.add(j);
				result++;
				for(int k=list.size()-1;k<list.size();k++){
					int pos=list.get(k);
					if(pos>col-1&&bf.charAt(pos-col)==c&&!list.contains(pos-col)){
						list.add(pos-col);
					}
					if(pos%col+1<col&&bf.charAt(pos+1)==c&&!list.contains(pos+1)){
						list.add(pos+1);
					}
					if(pos+col<bf.length()&&bf.charAt(pos+col)==c&&!list.contains(pos+col)){
						list.add(pos+col);
					}
					if(pos%col-1>=0&&bf.charAt(pos-1)==c&&!list.contains(pos-1)){
						list.add(pos-1);
					}
				}
			}
			str=scanner.nextLine().trim();
			ss=str.split(" ");
			col=Integer.parseInt(ss[0]);
			row=Integer.parseInt(ss[1]);
			System.out.printf("%d\n", result);
		}
		scanner.close();

	}

}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main{
	static Scanner sc = new Scanner(System.in);

	static int height;

	static int width;

	static char[][] map = new char[height][];

	public static void main(String[] args) {

		while (true) {
			height = Integer.parseInt(sc.next());
			width = Integer.parseInt(sc.next());
			if (height == 0 && width == 0) {
				break;
			}

			for (int i = 0; i < height; i++) {
				map[i] = sc.next().toCharArray();
			}
			int cnt = 0;
			Deque<int[]> s = new ArrayDeque<>();
			for (int i = 0; i < height; i++) {

				for (int j = 0; j < width; j++) {
					char target;
					if (map[i][j] == '@' || map[i][j] == '#' || map[i][j] == '*') {
						s.add(new int[] { i, j });
						target = map[i][j];
					} else {
						continue;
					}
					while (!s.isEmpty()) {
						int[] u = s.poll();

						int[] dx = { 1, 0, 0, -1 };
						int[] dy = { 0, 1, -1, 0 };
						for (int d = 0; d < 4; d++) {
							int nx = u[0] + dx[d];
							int ny = u[1] + dy[d];
							if (0 > nx || nx >= height || 0 > ny || ny >= width) {
								continue;
							}
							if (map[nx][ny] == target) {
								map[nx][ny] = '.';
								s.add(new int[] { nx, ny });
							}

						}

					}
					cnt++;
				}

			}
			System.out.println(cnt);
		}
	}

}

