				return;
			base=new int[H][W];
			for(int i=0;i<H;i++)
			{
				str=in.next();
				for(int j=0;j<W;j++)
				{
					if(str.charAt(j)=='@')
						base[i][j]=1;
					else if(str.charAt(j)=='#')
						base[i][j]=2;
					else if(str.charAt(j)=='*')
						base[i][j]=3;

				}
			}
			ans=0;
			for(int i=0;i<H;i++)
				for(int j=0;j<W;j++)
				{
					if(base[i][j]==1)
					{
						solve1(i,j,H,W);
						ans++;
					}
					else if(base[i][j]==2)
					{
						solve2(i,j,H,W);
						ans++;
					}
