				solve1(m-1,n,H,W);
			if(m+1<H&&base[m+1][n]==1)
				solve1(m+1,n,H,W);
			if(n-1>=0&&base[m][n-1]==1)
				solve1(m,n-1,H,W);
			if(n+1<W&&base[m][n+1]==1)
				solve1(m,n+1,H,W);
