						distribution(i, j);
					}
				}
			}
			System.out.println(ans);
		}
	}

	static void distribution(int i, int j) {
		mapB[i][j] = true;
		if (!mapB[i - 1][j] && mapC[i - 1][j] == mapC[i][j]) {
			distribution(i - 1, j);
		}
		if (!mapB[i + 1][j] && mapC[i + 1][j] == mapC[i][j]) {
			distribution(i + 1, j);
		}
		if (!mapB[i][j - 1] && mapC[i][j - 1] == mapC[i][j]) {
			distribution(i, j - 1);
		}
		if (!mapB[i][j + 1] && mapC[i][j + 1] == mapC[i][j]) {
			distribution(i, j + 1);
		}
	}
