        for(int i = 0; i < h; i++) {
            grid[i] = sc.next().toCharArray();
        }
    }

    public static void dfs(int i, int j , char c) {
        // stopping condition
        if(i < 0 || i >= h || j < 0 || j >= w) return;
        if(grid[i][j] != c) return;

        // marking where already visit
        grid[i][j] = '.';

        // recursion
        for(int k = 0; k < 4; k++) dfs(i + dx[k], j + dy[k], c);
    }

    public static void solve() {
        // dfs
        for(int i = 0; i < h; i++) {
            for(int j = 0; j < w; j++) {
                if(grid[i][j] != '.') {
                    ans++;
                    dfs(i, j, grid[i][j]);
                }

            }
        }

        System.out.println(ans);
    }

    public static void main(String[] args) {
        while(true) {
            h = sc.nextInt();
            w = sc.nextInt();
            if(h == 0 && w == 0) return;
            load();
            solve();
        }

    }

}

import java.util.*;
import java.io.*;

public class Main {

	public int calculate(char[][] map){
		int n = map.length;
		int m = map[0].length;
		int counter = 0;
		for(int i = 1; i < map.length-1; i++){
			for(int j = 1; j < map[0].length-1; j++){
				if( map[i][j] == '.' ){
					continue;
				}
				counter++;
				char key = map[i][j];
				Set<Integer> set = new HashSet<Integer>();
				Set<Integer> next = new HashSet<Integer>();
				next.add(i*n+j);
				while( next.size() != 0 ){
					for(Integer x : next){
						set.add(x);
					}
					next.clear();
					for(Integer x : set){
						int a = x/n;
						int b = x%n;
						if( map[a+1][b] == key && !set.contains((a+1)*n+b) ){
							next.add((a+1)*n+b);
						}
						if( map[a-1][b] == key && !set.contains((a-1)*n+b) ){
							next.add((a-1)*n+b);
						}
						if( map[a][b+1] == key && !set.contains(a*n+b+1) ){
							next.add((a*n+b+1));
						}
						if( map[a][b-1] == key && !set.contains(a*n+b-1) ){
							next.add((a*n+b-1));
						}
					}
				}
				for(Integer x : set){
					int a = x/n;
					int b = x%n;
					map[a][b] = '.';
				}
			}
		}
		return counter;
	}
	public void solve() throws IOException {
		int n, m;
		while( (n = nextInt()) != 0 | (m = nextInt()) != 0 ){
			String[] temp = new String[n];
			for(int i = 0; i < n; i++){
				temp[i] = nextToken();
			}			
			char[][] map = new char[n+2][m+2];
			for(int i = 0; i < map.length; i++){
				map[i][0] = '.';
				map[i][map[0].length-1] = '.';
			}
			for(int i = 0; i < map[0].length; i++){
				map[0][i] = '.';
					map[map.length-1][i] = '.';
			}
			for(int i = 1; i < map.length-1; i++){
				for(int j = 1; j < map[0].length-1; j++){
					map[i][j] = temp[i-1].charAt(j-1);
				}
			}
			System.out.println(calculate(map));
		}
	}		
	public static void main (String args[]) throws IOException{
		new Main().run();
	}
	BufferedReader reader;
	StringTokenizer tokenizer;
	PrintWriter writer;

	public void run() throws IOException{
		try{
			reader = new BufferedReader(new InputStreamReader(System.in));
			tokenizer = null;
			writer = new PrintWriter(System.out);
			solve();
			reader.close();
			writer.close();
		} catch (Exception e){
			e.printStackTrace();
			System.exit(1);
		}
	}
	public int nextInt() throws IOException{
		return Integer.parseInt(nextToken());
	}
	public String nextToken() throws IOException{
		while( tokenizer == null || !tokenizer.hasMoreTokens() ){
			tokenizer = new StringTokenizer(reader.readLine());
		}
		return tokenizer.nextToken();
	}
}

import java.util.*;

public class Main {
	Scanner sc = new Scanner(System.in);
	int map[][];
	int dx[] = {1,-1,0,0};
	int dy[] = {0,0,1,-1};
	void dfs(int h,int w,int cost,int H,int W){
		map[h][w] = 0;
		if(cost > 0){
			for(int i = 0;i < 4;i++){
				int ax = w + dx[i];
				int ay = h + dy[i];
				if(ax >= 0 && ax < W && ay >= 0 && ay < H){
					if(map[ay][ax] == cost){
						dfs(ay,ax,map[ay][ax],H,W);
					}
				}
			}
		}
	}
	void doIt() { 
		while(true){
			int W = sc.nextInt();
			int H = sc.nextInt();
			ArrayList<Character> array= new ArrayList<Character>();
			if(H + W == 0)break;
			map = new int[H][W];
			for(int h = 0;h < H;h++){
				String str = sc.next();
				char ctr[] = str.toCharArray();
				for(int w = 0;w < W;w++){
					for(int k = 0;k < array.size();k++){
						if(ctr[w] == array.get(k)){
							map[h][w] = k + 1;
						}
					}if(map[h][w] == 0){
						array.add(ctr[w]);
						map[h][w] = array.size();
					}
				}
			}
			int cnt = 0;
			for(int h = 0;h < H;h++){
				for(int w = 0;w < W;w++){
					if(map[h][w] > 0){
						cnt++;
						dfs(h,w,map[h][w],H,W);
					}
				}
			}
			System.out.println(cnt);
		}
     }
    public static void main(String[] args) {
    	new Main().doIt();
    }
}

import java.io.BufferedReader;
