	static int w;

	public static void main(String[] args) throws Exception, IOException {
		h = in.nextInt();
		w = in.nextInt();
		land = in.nextCharArray2d(h, w);

		separate = new int[h][w];
		int owner = 0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
