	public void grouping(String[][] data, int[][] label, int w, int h, int x, int y){
		for(int n=0; n<4; n++){
			int i = x + offset[n][0];
			int j = y + offset[n][1];
			if(i>=0 && j>=0 && i<w && j<h){
				if(label[j][i] == 0){
					if(data[j][i].equals(data[y][x])){
						label[j][i] = label[y][x];
						grouping(data, label, w, h, i, j);
					}
				}
			}
		}
	}
