        }
        return true;
    }

    public static void dfs(int i, int j , char c) {
        // stopping condition
        if(i < 0 || i >= h || j < 0 || j >= w) return;
        if(grid[i][j] == '.') return;

        // marking
        // grid[i][j] = '.';

        // recursion
        if(grid[i][j] == c) {
            for(int k = 0; k < 4; k++) {
                grid[i][j] = '.';
                dfs(i+1, j, c);
                dfs(i, j+1, c);
                dfs(i-1, j, c);
                dfs(i, j-1, c);
            }
        }
    }

    public static void solve() {
        int ans = 0;

        // dfs
        for(int i = 0; i < h; i++) {
            for(int j = 0; j < w; j++) {
                if(grid[i][j] != '.') {
                    ans++;
                    dfs(i, j, grid[i][j]);
                }

            }
        }

        System.out.println(ans);
    }

    public static void main(String[] args) {
        while(read()) solve();
    }

}

