		for(int i = 1; i <= h; i++) {
			String line = sc.next();
			for(int j = 1; j <= w; j++) {
				field[i][j] = line.charAt(j - 1);
			}
		}
		return true;
	}

	static int solve() {
		int ret = 0;
		for(int i = 1; i <= h; i++) {
			for(int j = 1; j <= w; j++) {
				if(field[i][j] != ' ') {
					ret++;
					rec(j, i, field[i][j]);
				}
			}
		}

		return ret;
	}

	static void rec(int x, int y, char c) {
		for(int k = 0; k < 4; k++) {
			int nx = x + dx[k], ny = y + dy[k];
			if(field[ny][nx] == c) {
				field[ny][nx] = ' ';
				rec(nx, ny, c);
			}
		}
	}
}

