class Program
{
	private static int h, w;
	private static char[][] m = new char[100][];
	private static int[] dx = new[] {0, 1, 0, -1, 1, 1, -1, -1};
	private static int[] dy = new[] {1, 0, -1, 0, 1, -1, 1, -1};
	public static int Main()
	{
		Scanner cin = new Scanner();
		while (true)
		{
			h = cin.nextInt();
			w = cin.nextInt();
			if (h == 0 || w == 0)
			{
				break;
			}
			int ans = 0;
			for (int i = 0; i < h; i++)
			{
