using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ConsoleApplication1
{
    struct Position { internal int x, y; }

    class PropertyDistribution
    {
        readonly int H, W;

        readonly int[] moveX = new int[] { 1, 0, -1, 0 };
        readonly int[] moveY = new int[] { 0, 1, 0, -1 };

        char[][] map;
        int count;

        public PropertyDistribution(int H, int W)
        {
            this.H = H;
            this.W = W;

            map = new char[H][];
        }

        public void MakeMap(string source, int n)
        {
            map[n] = source.ToCharArray();
        }

        public int Count()
        {
            count = 0;

            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    if (map[i][j] != '0')
                    {
                        Position pos;
                        pos.x = j;
                        pos.y = i;

                        CheckMap(pos, map[i][j]);
                        count++;
                    }
                }
            }
            return count;
        }

        private void CheckMap(Position pos, char ch)
        {
            Stack<Position> stk = new Stack<Position>();

            stk.Push(pos);

            while (stk.Count > 0)
            {
                Position cur = stk.Pop();
                map[cur.y][cur.x] = '0';

                for (int i = 0; i < 4; i++)
                {
                    Position next;
                    next.x = cur.x + moveX[i];
                    next.y = cur.y + moveY[i];

                    if (IsValid(next) && map[next.y][next.x] == ch)
                    {
                        stk.Push(next);
                    }
                }
            }
        }

        private bool IsValid(Position pos)
        {
            if (pos.x < 0) return false;
            if (pos.y < 0) return false;
            if (pos.x >= W) return false;
            if (pos.y >= H) return false;
            return true;
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            StringBuilder sb = new StringBuilder();

            while (true)
            {
                string[] input = Console.ReadLine().Split(' ');
                int H = int.Parse(input[0]);
                int W = int.Parse(input[1]);

                if (H == 0 && W == 0) break;

                PropertyDistribution PD = new PropertyDistribution(H, W);

                for (int i = 0; i < H; i++)
                {
                    PD.MakeMap(Console.ReadLine(), i);
                }

                sb.AppendLine(PD.Count().ToString());
            }
            Console.Write(sb);
        }
    }
}

