    class Searcher {
        int[,] section;

        public int searchProperty(string[,] data){
            section = new int[data.GetLength(0) , data.GetLength(1)];
            int num_Div = 1;
            bool full = true;

            for (int i = 0; i < data.GetLength(0); i++) {
                int leftEdge = 0;
                int rightEdge = 0;
                for (int start = 0; start < data.GetLength(1); start++) {
                    if (section[i, start] == 0) {
                        leftEdge = start;
                        break;
                    }   
                }
                do {
                    int cur = leftEdge;
                    do {
                        if (section[i, cur] == 0) {
                            section[i, cur] = num_Div;
                        }
                        cur++;
                        if (cur == data.GetLength(1)) {
                            break;
                        }
                    } while (data[i, cur] == data[i, leftEdge]);
                    rightEdge = cur;

                    for (int w = i + 1; w < data.GetLength(0); w++) {
                        int connection = 0;
                        for (int r = leftEdge; r < rightEdge; r++) {
                            if (data[w, r] == data[w - 1, r] && data[w, r] == data[i , leftEdge]) {
                                section[w, r] = num_Div;
                                if (r != 0) {
                                    for (int back = r - 1; back >= 0; back--) {
                                        if (data[w, back] == data[i, back] && section[w, back] == 0) {
                                            section[w, back] = num_Div;
                                        } else {
                                            break;
                                        }
                                    }
                                    for (int forward = r + 1; forward < data.GetLength(1); forward++) {
                                        if (data[w, forward] == data[i, forward] && section[w, forward] == 0) {
                                            section[w, forward] = num_Div;
                                        } else {
                                            break;
                                        }
                                    }
                                }
                                connection++;
                                continue;
                            }
                        }
                        if (connection == 0) {
                            break;
                        }
                    }
                    if (section[i, rightEdge-1] == 0) {
                        leftEdge = rightEdge;
                    } else {
                        for (int q = rightEdge; q < data.GetLength(1); q++) {
                            if (section[i, q] == 0 || q == data.GetLength(1) - 1) {
                                leftEdge = q;
                                break;
                            }
                        }
                    }
                    num_Div++;

                    full = true;
                    for (int k = 0; k < data.GetLength(1); k++){
                        if (section[i,k] == 0) {
                            full = false;
                        }
			        }
                } while (!full);
            }

            return num_Div - 1;
        }
    }

}

