using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static readonly int[] di = { 0, 0, -1, 1 };
    static readonly int[] dj = { -1, 1, 0, 0 };
    int H, W;
    string[] grid;
    bool IsInside(int i, int j) { return i >= 0 && i < H && j >= 0 && j < W; }

    void BFS(int si, int sj, bool[,] seen)
    {
        var que = new Queue<int>();
        que.Enqueue(si);
        que.Enqueue(sj);
        seen[si, sj] = true;

        while (que.Count > 0)
        {
            int i = que.Dequeue();
            int j = que.Dequeue();

            for (int d = 0; d < di.Length; d++)
            {
                int ni = i + di[d], nj = j + dj[d];
                if (IsInside(ni, nj) && !seen[ni, nj] && grid[ni][nj] == grid[i][j])
                {
                    seen[ni, nj] = true;
                    que.Enqueue(ni);
                    que.Enqueue(nj);
                }
            }
        }
    }

    void Solve()
    {
        var read = new Read();
        while (true)
        {
