        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (!used[i, j]) {
                    char c = f[i, j];
                    Queue<Point> q = new Queue<Point>();
                    q.Enqueue(new Point(j, i));
                    while (q.Count > 0) {
                        var p = q.Dequeue();
                        used[p.y, p.x] = true;
