class Program
{
    static readonly int[] di = { 0, 0, -1, 1 };
    static readonly int[] dj = { -1, 1, 0, 0 };
    int H, W;
    string[] grid;
    bool IsInside(int i, int j) { return i >= 0 && i < H && j >= 0 && j < W; }

    void BFS(int si, int sj, bool[,] seen)
    {
        var que = new Queue<Tuple<int, int>>();
        que.Enqueue(new Tuple<int, int>(si, sj));
        seen[si, sj] = true;

        while (que.Count > 0)
        {
            var curr = que.Dequeue();
            int i = curr.Item1, j = curr.Item2;

            for (int d = 0; d < di.Length; d++)
            {
                int ni = i + di[d], nj = j + dj[d];
                if (IsInside(ni, nj) && !seen[ni, nj] && grid[ni][nj] == grid[i][j])
                {
                    seen[ni, nj] = true;
                    que.Enqueue(Tuple.Create(ni, nj));
                }
            }
        }
    }

    void Solve()
    {
        var read = new Read();
        while (true)
        {
            H = read.NextInt(); W = read.NextInt();
            if (H == 0 && W == 0) break;
            grid = Enumerable.Range(0, H).Select(i => Console.ReadLine()).ToArray();
            int ans = 0;
            var seen = new bool[H, W];

            for (int i = 0; i < H; i++)
                for (int j = 0; j < W; j++)
                    if (!seen[i, j])
                    {
                        ans++;
                        BFS(i, j, seen);
                    }

            Console.WriteLine(ans);
        }
        Console.ReadLine();
    }

