namespace PokerPlaying {
    class Class2 {
        int[,] section;
        readonly int[] dY = new int[]{0, 1, 0, -1};
        readonly int[] dX = new int[]{ 1, 0, -1, 0 };
        int num_Div = 1;

        static void Main(string[] args) {
            new Class2().solve();
        }
        void solve() {
            while (true) {
                string lengthinput = Console.ReadLine();
                if (lengthinput == "0 0") {
                    return;
                }
                var divL = lengthinput.Split(' ');
                int x_length = int.Parse(divL[1]);
                int y_length = int.Parse(divL[0]);

                string[,] input = new string[y_length, x_length];
                section = new int[input.GetLength(0), input.GetLength(1)];
                for (int y = 0; y < y_length; y++) {
                    string data = Console.ReadLine();
                    for (int x = 0; x < x_length; x++) {
                        input[y, x] = data.Substring(x, 1);
                    }
                }
                Console.WriteLine(searchProperty(input));
            }
        }
        public int searchProperty(string[,] data) {

            int num_Div = 1;

            for (int i = 0; i < data.GetLength(0); i++) {
                for (int j = 0; j < data.GetLength(1); j++) {
                    if (section[i, j] == 0) {
                        compare(data, data[i, j], j, i);
                        num_Div++;
                    }
                }
            }
            return num_Div - 1;
        }

        void compare(string[,] data, string comparison, int x, int y) {
            if (!isValid(x, y)) return;
            if (data[y, x] != comparison || section[y, x] != 0) return;
            section[y, x] = num_Div;
            for (int i = 0; i < dX.Length; i++) {
                compare(data, comparison, x + dX[i], y + dY[i]);
            }
        }

        bool isValid(int x, int y) {
            if (x >= section.GetLength(1) || y >= section.GetLength(0)
                || x < 0 || y < 0) {
                return false;
            } else return true;
        }
    }
}

