		static void g(int[][] k, int x, int y, int c)
		{
			if (k[x][y] != c) return;
			k[x][y] = 0;
			g(k, x - 1, y, c);
			g(k, x, y - 1, c);
			g(k, x + 1, y, c);
			g(k, x, y + 1, c);
		}
	}
}

