public class Hello
{
    public static void Main()
    {
        var dx = new int[] { 0, 1, 0, -1 };
        var dy = new int[] { 1, 0, -1, 0 };
        var st = new Queue<Po>();
        while (true)
        {
            string[] line = Console.ReadLine().Trim().Split(' ');
            var h = int.Parse(line[0]);
            var w = int.Parse(line[1]);
            if (h == 0 && w == 0) break;
            var map = new int[h, w];
            for (int i = 0; i < h; i++)
            {
                var s = Console.ReadLine().Trim();
                for (int j = 0; j < w; j++)
                    if (s[j] == '#') map[i, j] = 1;
                    else if (s[j] == '*') map[i, j] = 2;
            }
            var count = 0;
            for (int i = 0; i < h; i++)
                for (int j = 0; j < w; j++)
                    if (map[i, j] <= 2)
                    {
                        st.Enqueue(new Po { x = i, y = j });
                        goDfs(map, st, map[i, j], dx, dy ,h,w);
                        count++;
                    }
            Console.WriteLine(count);
        }
    }
    public static void goDfs(int[,] map, Queue<Po> st, int c, int[] dx, int[] dy ,int h ,int w)
    {
        while (st.Count() > 0)
        {
            var a = st.Dequeue();
            map[a.x, a.y] = 3;
            for (int i = 0; i < 4; i++)
            {
                var nx = a.x + dx[i];
                var ny = a.y + dy[i];
                if (nx >= 0 && nx < h && ny >= 0 && ny < w && map[nx, ny] == c)
                    st.Enqueue(new Po { x = nx, y = ny });
            }
        }
    }
}

