				}
			}
		}

		foreach (i; 0..x[0]) {
			foreach (j; 0..x[1]) {
				if (area[i][j] == '.') continue;
				cnt++;
				solve(i, j, area[i][j]);
			}
		}
		cnt.writeln;
	}
