# UNION-FIND library
class UnionSet:
	def __init__(self, nmax):
		self.size = [1]*nmax
		self.id = [i for i in range(nmax+1)]
	def root(self, i):
		while i != self.id[i]:
			self.id[i] = self.id[self.id[i]]
			i = self.id[i]
		return i
	def connected(self, p, q): return self.root(p) == self.root(q)
	def unite(self, p, q):
		i, j = self.root(p), self.root(q)
		if i == j: return
		if self.size[i] < self.size[j]:
			self.id[i] = j
			self.size[j] += self.size[i]
		else:
			self.id[j] = i
			self.size[i] += self.size[j]
# UNION-FIND library

while 1:
	H, W = map(int, input().split())
	if H == 0 and W == 0: break
	tbl = ['']*H
	for r in range(H): tbl[r] = input()
	u = UnionSet(H*W)
	rr = 0
	for r in range(H):
		for c in range(W):
			if c+1 < W and tbl[r][c] == tbl[r][c+1]: u.unite(rr+c, rr+c+1)
			if r+1 < H and tbl[r][c] == tbl[r+1][c]: u.unite(rr+c, rr+W+c)
		rr += W
	ans = 0
